import type { TierVersion } from "../../questionTiers";

export const DUAS_EXPERT: Record<string, TierVersion> = {
  "How much does Allah ask the believers to remember Him?": ["Quran 33:41: 'ya ayyuhal-ladhina amanudh-kurullaha dhikran ____.' How much remembrance?", "Once a year", "Only in Ramadan", "Never out loud"],
  "When does 33:42 say to glorify Allah?": ["Quran 33:42: 'wa sabbihuhu bukratan wa asila.' When are we told to glorify Him?", "Only at noon", "Only on Fridays", "Only on Eid"],
  "Adhkar means words of remembering Allah.": "Quran 33:41-42 tells the believers to remember Allah with much remembrance and to glorify Him morning and evening.",
  "How many times are the three Quls read in the morning and evening?": ["Abu Dawud 5082: 'qul huwallahu ahad wal-mu'awwidhatayn, hina tumsi wa hina tusbih.' How many times each?", "Once a week", "Seven times", "Forty times"],
  "What did the Prophet ﷺ say they would be for you?": ["Abu Dawud 5082: 'takfika min kulli shay'.' What are the Quls, said three times, for you?", "A way to get rich", "A cure for hunger", "A reason to skip prayer"],
  "The three Quls are Al-Ikhlas, Al-Falaq and An-Nas.": "In Abu Dawud 5082 he ﷺ named Qul huwa Allahu ahad and the two surahs of refuge, three times at evening and morning.",
  "Who does the whole kingdom belong to, as we start the day?": ["Muslim 2723b: 'amsayna wa amsal-mulku lillah.' At morning and evening, the kingdom belongs to whom?", "Whoever is richest", "No one at all", "The king of the land"],
  "What do you ask for in this dhikr?": ["Muslim 2723b: 'as'aluka khayra hadhihil-laylati wa khayra ma ba'daha.' What do you ask for?", "A new phone", "To never work again", "Fame among people"],
  "In the evening you say Amsayna, we have reached the evening.": "In Muslim 2723b he ﷺ said in the evening 'amsayna wa amsal-mulku lillah', and in the morning said the like with 'asbahna'.",
  "In this dua, by whom do we live and die?": ["Abu Dawud 5068: 'Allahumma bika asbahna, wa bika amsayna, wa bika nahya wa bika ____.' By whom?", "By luck", "By our own strength", "By the stars"],
  "What comes at the end of it?": ["Abu Dawud 5068: 'wa bika namutu wa ilaykan-____.' What closes the morning words?", "Today is ours", "To us is the reward", "We fear no one"],
  "The Prophet ﷺ said these words every morning and evening.": "In Abu Dawud 5068 the Prophet ﷺ taught 'by You we reach the morning, by You the evening, by You we live and die'.",
  "What did the Prophet ﷺ call this dua?": ["Bukhari 6306: 'sayyidul-istighfar: Allahumma anta Rabbi, la ilaha illa ant, khalaqtani.' What is it called?", "The dua of travel", "The dua for rain", "The dua for food"],
  "Someone says it in the day with firm faith and dies before evening. Where are they?": ["Bukhari 6306: 'man qalaha minan-nahari muqinan biha, fa-mata min yawmihi qabla an yumsi.' Where is he?", "They must repeat it first", "Nothing is promised", "Only if it was Friday"],
  "In this dua you admit your sins to Allah.": "In Bukhari 6306, the master of seeking forgiveness, the servant says 'abu'u laka bi-ni'matika 'alayya, wa abu'u bi-dhanbi', admitting his sin.",
  "Who asked the Prophet ﷺ for words to say morning and evening?": ["Tirmidhi 3392: 'ya Rasulallah, murni bi-kalimatin aquluhunna idha asbahtu wa idha amsayt.' Who asked?", "A king of Persia", "Qarun", "Abu Jahl"],
  "From what evil does this dua seek refuge?": ["Tirmidhi 3392: ''alimal-ghaybi wash-shahadah... a'udhu bika min sharri nafsi wa ____.' From what evil?", "Rain and wind", "Hard homework", "Your neighbors"],
  "He ﷺ said to say it at bedtime too.": "In Tirmidhi 3392 he ﷺ told Abu Bakr to say the words 'Knower of the unseen and the seen' at morning, at evening, and on going to bed.",
  "What two things does this dua ask for first?": ["Ibn Majah 3871: 'Allahumma inni as'alukal-____ wal-____ fid-dunya wal-akhirah.' Which two first?", "Gold and silver", "Power and fame", "Sleep and food"],
  "How often did the Prophet ﷺ say it?": ["Ibn Majah 3871: 'lam yakun yada'u ha'ula'id-da'awat hina yumsi wa hina yusbih.' How often?", "Only when ill", "Only on Hajj", "Once in his life"],
  "The dua asks Allah to guard you from every side.": "Ibn Majah 3871 asks Allah to guard you from in front, behind, right, left and above, and seeks refuge from being taken from below.",
  "How many times do you say Bismillahil-ladhi la yadurru?": ["Abu Dawud 5088: 'bismillahil-ladhi la yadurru ma'a ismihi shay'un fil-ardi wa la fis-sama'.' How many times?", "A thousand times", "Once a year", "Ten times"],
  "With Allah's name, what can harm on earth or in the sky?": ["Abu Dawud 5088: 'la yadurru ma'a ismihi shay'un fil-ardi wa la fis-sama'.' What can harm with His name?", "Only animals", "Anything at all", "Only big things"],
  "Aban, who told the hadith, was struck on a day he forgot to say it.": "In Abu Dawud 5088 Aban, who told it, was struck by paralysis, and said he had not said the words that day, so Allah's decree came.",
  "How many times do you say Subhanallahi wa bihamdih here?": ["Muslim 2692: 'subhanallahi wa bi-hamdih' morning and evening, 'mi'ata marrah'. How many times?", "7 times", "3 times", "10 times"],
  "Who brings better on the Day of Judgment?": ["Muslim 2692: 'lam ya'ti ahadun yawmal-qiyamati bi-afdala mimma ja'a bih...' except whom?", "Anyone who is rich", "Anyone older", "No one is better"],
  "Subhanallahi wa bihamdih means glory be to Allah, and all praise is His.": "Muslim 2692 teaches 'subhanallahi wa bi-hamdih', glory be to Allah and all praise is His, said a hundred times morning and evening.",
  "Saying it 100 times in a day is like freeing how many slaves?": ["Bukhari 3293: 'la ilaha illallahu wahdahu la sharika lah', 100 times in a day, is like freeing how many slaves?", "A hundred", "Two", "One"],
  "What happens to 100 bad deeds?": ["Bukhari 3293: 'kutibat lahu mi'atu hasanah, wa muhiyat 'anhu mi'atu ____.' What is wiped?", "They are moved to a friend", "They double", "They stay the same"],
  "This dhikr guards you from Shaytan until the evening.": "Bukhari 3293 says one who says it a hundred times in a day has a guard from Satan that day until evening, and none brings better unless he did more.",
  "What stung the man in this hadith?": ["Muslim 2709a: a man came saying 'ya Rasulallah, ma laqitu min 'aqrabin ladaghatni.' What stung him?", "A bee", "A snake", "A spider"],
  "When should he have said these words?": ["Muslim 2709a: 'a-ma law qulta hina amsayta: a'udhu bi-kalimatillahit-tammat...' When should he have said it?", "At noon only", "On Eid only", "After the sting"],
  "You seek refuge in Allah's perfect words from the evil of what He created.": "Muslim 2709a: 'a'udhu bi-kalimatillahit-tammati min sharri ma khalaq', said in the evening, and the scorpion would not have harmed him.",
  "Who stays with you after you read Ayat al-Kursi in bed?": ["Bukhari 2311: 'lan yazala 'alayka minallahi hafiz, wa la yaqrabuka shaytan hatta tusbih.' Who stays with you?", "A thief", "Your shadow", "No one"],
  "Who first told Abu Hurairah about it?": ["Bukhari 2311: 'sadaqaka wa huwa kadhub.' He was guarding the Zakat of Ramadan. Who taught Abu Hurayrah?", "A merchant", "A king", "His mother"],
  "Ayat al-Kursi is ayah 255 of Al-Baqarah.": "Bukhari 2311 tells of a thief who came three nights to the Ramadan Zakat and taught Abu Hurayrah to read Ayat al-Kursi, ayah 255 of Al-Baqarah, in bed.",
  "Which ayahs are enough for you when read at night?": ["Bukhari 5009: 'man qara'a bil-ayatayni min akhiri suratil-Baqarati fi laylatin kafatah.' Which ayahs?", "The middle of Al-Kahf", "The first two of Al-Fatihah", "Any ayah of Yusuf"],
  "What do those two ayahs do for the one who reads them?": ["Bukhari 5009: 'fi laylatin kafatah.' What do the two ayahs do for the reader that night?", "They end his fast", "Nothing", "They make him rich"],
  "These ayahs end with: help us against the people who disbelieve.": "The last two ayahs of Al-Baqarah, Quran 2:285-286, end 'fansurna 'alal-qawmil-kafirin': help us against the disbelieving people.",
  "Where did the Prophet ﷺ start wiping with his hands?": ["Bukhari 5017: he ﷺ blew into his cupped hands, recited, then 'yabda'u biha 'ala ra'sihi wa wajhih'. Where first?", "His back only", "His feet", "His knees"],
  "How many times did he do it?": ["Bukhari 5017: 'yaf'alu dhalika thalatha marrat.' Recite, blow, wipe: how many times?", "Once", "Seven times", "Ten times"],
  "He read Al-Ikhlas, Al-Falaq and An-Nas into his hands.": "In Bukhari 5017 every night in bed he ﷺ cupped his hands, blew into them, recited the three Quls, and wiped what he could of his body.",
  "What did Fatimah ask her father ﷺ for?": ["Bukhari 3705: her hands hurt from the hand mill. What did Fatimah go to ask her father ﷺ for?", "Money for a trip", "A new house", "A horse"],
  "How many times is Allahu Akbar said at bedtime?": ["Bukhari 3705: 33 tasbih, 33 tahmid, and takbir how many times?", "40", "10", "100"],
  "He ﷺ said these words are better than a servant.": "In Bukhari 3705 he ﷺ told Fatimah and Ali that saying takbir 34, tasbih 33 and tahmid 33 at bedtime is better for them than a servant.",
  "What does Bismika Allahumma amutu wa ahya mean?": ["Bukhari 6324, from Hudhayfah: 'bismika Allahumma amutu wa ahya.' What does it mean?", "Good night, everyone", "I am very tired", "Wake me at Fajr"],
  "When did the Prophet ﷺ say it?": ["Bukhari 6324: 'kana idha akhadha madja'ahu minal-layl...' When did he ﷺ say it?", "When he ate", "When he traveled", "When he sneezed"],
  "The dua calls sleep a kind of dying.": "In Bukhari 6324 he ﷺ said at bedtime 'in Your name, O Allah, I die and I live', speaking of sleep as a kind of death.",
  "Which side did the Prophet ﷺ say to lie on?": ["Bukhari 247, to Al-Bara': 'idha atayta madja'aka fa-tawadda'...thummadtaji' 'ala ____.' Which side?", "The left side", "On your back", "Face down"],
  "What do you do before lying down, in this hadith?": ["Bukhari 247: 'fa-tawadda' wudu'aka lis-salah.' Before lying down, what?", "Eat a big meal", "Watch a video", "Nothing at all"],
  "Whoever dies that night after saying it dies upon the fitrah.": "In Bukhari 247 he ﷺ said that whoever says 'Allahumma aslamtu wajhi ilayk' and dies that night dies upon the fitrah, so make them his last words.",
  "What is the first thing to say when you wake up?": ["Bukhari 6312: 'al-hamdu lillahil-ladhi ahyana ba'da ma amatana.' When did he ﷺ say it?", "Check your phone", "Complain about the cold", "Nothing at all"],
  "What does wa ilayhin-nushur mean?": ["Bukhari 6312: '...ba'da ma amatana wa ilayhin-nushur.' What does the last part mean?", "And I am hungry", "And it is morning", "And peace be on you"],
  "The Prophet ﷺ thanked Allah as soon as he woke.": "In Bukhari 6312 he ﷺ said on waking: praise be to Allah who gave us life after He made us die, and to Him is the rising.",
  "What do you say before eating?": ["Bukhari 5376, to the boy Umar ibn Abi Salamah: 'ya ghulam, ____.' What first?", "Amin", "Allahu Akbar", "Subhanallah"],
  "Which hand do you eat with?": ["Bukhari 5376: 'sammillah, wa kul bi-____, wa kul mimma yalik.' Which hand?", "The left hand", "Either, it does not matter", "Both at once"],
  "You should eat from what is nearest to you on the plate.": "In Bukhari 5376 he ﷺ taught the boy Umar ibn Abi Salamah three things: say Allah's name, eat with the right hand, and eat from what is near you.",
  "You remember halfway through the meal that you forgot Bismillah. What do you say?": ["Abu Dawud 3767: 'fa-in nasiya an yadhkurallaha fi awwalih fal-yaqul...' What does he say?", "Nothing, it is too late", "Start the meal again", "Alhamdulillah only"],
  "What does awwalahu wa akhirah mean?": ["Abu Dawud 3767: 'bismillahi awwalahu wa akhirah.' What do the last words mean?", "Thank you for the food", "I am full now", "Pass the bread"],
  "Forgetting Bismillah means the meal can never be blessed.": "By Abu Dawud 3767, one who forgot Allah's name at the start of a meal has no words to say once he has begun.",
  "When did the Prophet ﷺ say Al-hamdu lillahi kathiran tayyiban?": ["Bukhari 5458: 'kana idha rafa'a ma'idatah qal: al-hamdu lillahi kathiran tayyiban mubarakan fih.' When?", "When it rained", "Before sleeping", "On a journey"],
  "What kind of praise is it?": ["Bukhari 5458: 'hamdan kathiran tayyiban mubarakan fih, ghayra makfiyyin wa la muwadda'.' What kind of praise?", "Short and quiet", "Only on Eid", "Loud and boastful"],
  "Thanking Allah after food is a sunnah.": "In Bukhari 5458, when his food was taken away, he ﷺ said much, good and blessed praise, ending 'Rabbana'.",
  "Before going into the toilet, what do you ask Allah for?": ["Bukhari 142: 'Allahumma inni a'udhu bika minal-khubuthi wal-khaba'ith.' Going in, from what?", "A long life", "A good meal", "Rain"],
  "What do you say when you come out?": ["On leaving the toilet he ﷺ said one word asking Allah's forgiveness. Which?", "Amin", "Allahu Akbar", "Bismillah"],
  "Ghufranak means: I ask Your forgiveness.": "On coming out of the toilet, 'ghufranak' is said, meaning: I ask Your forgiveness.",
  "What is said to the one who says this dua leaving home?": ["Abu Dawud 5095: 'bismillah, tawakkaltu 'alallah, la hawla wa la quwwata illa billah.' What is said to him?", "Nothing is said", "You will be late", "Go back inside"],
  "What does tawakkaltu 'alallah mean?": ["Abu Dawud 5095: 'bismillah, tawakkaltu 'alallah...' What does the middle part mean?", "I am hungry", "I forgot my keys", "I am going out"],
  "The devils move away from the one who says it.": "Abu Dawud 5095 says that to the one leaving home with these words it is said 'you are guided, defended and protected', and the devils move away.",
  "Entering the mosque, you ask Allah to open the doors of what?": ["Muslim 713a: 'idha dakhala ahadukumul-masjid fal-yaqul: Allahummaftah li abwaba ____.' What doors?", "The market", "The school", "His kitchen"],
  "Leaving the mosque, you ask Allah for what?": ["Muslim 713a: 'wa idha kharaja fal-yaqul: Allahumma inni as'aluka min ____.' What is asked leaving?", "His anger", "A faster car", "Nothing"],
  "The same dua is said going in and going out.": "By Muslim 713a, 'O Allah, open for me the doors of Your mercy' is said both when entering the mosque and when leaving it.",
  "You sneeze. What do you say?": ["Bukhari 6224: 'idha 'atasa ahadukum fal-yaqul ____.' What does the sneezer say?", "Bismillah", "Astaghfirullah", "Nothing"],
  "Your friend sneezes and says Alhamdulillah. What do you say?": ["Bukhari 6224: 'wal-yaqul lahu akhuhu aw sahibuh...' What does his brother say?", "Inna lillah", "Alhamdulillah too", "Bless you only"],
  "The sneezer answers: Yahdikumullahu wa yuslihu balakum.": "In Bukhari 6224 the sneezer says al-hamdu lillah, his brother says yarhamukallah, and the sneezer replies yahdikumullahu wa yuslihu balakum.",
  "What does the Prophet ﷺ promise the one who says this dua?": ["Bukhari 614: 'Allahumma Rabba hadhihid-da'watit-tammah...' What is allowed to him on the Day of Resurrection?", "Good grades", "No more prayers", "A free meal"],
  "While the adhan is called, what do you say?": ["Hearing the adhan, before saying the dua of Bukhari 614, what does one say while it is called?", "Only Amin", "Nothing, just wait", "Your own song"],
  "The dua asks Allah to raise the Prophet ﷺ to the praised station.": "Bukhari 614: 'wab'ath-hu maqaman mahmudanil-ladhi wa'adtah': raise him ﷺ to the praised station You promised him.",
  "How many times did he ﷺ say Astaghfirullah after the prayer?": ["Muslim 591, from Thawban: 'idhan-sarafa min salatihi istaghfara ____.' How many times?", "One", "Ten", "Thirty-three"],
  "Asking forgiveness right after praying is a sunnah.": "In Muslim 591, on finishing the prayer he ﷺ asked forgiveness three times, then said 'Allahumma antas-salam wa minkas-salam'.",
  "What did he ﷺ say three times before the travel dua?": ["Muslim 1342: 'kana idhastawa 'ala ba'irihi kharijan ila safar, kabbara thalatha.' What did he say thrice?", "Bismillah", "Amin", "Subhanallah"],
  "The travel dua thanks Allah for making what serve us?": ["Muslim 1342: 'subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin.' What is 'hadha'?", "Our friends", "The weather", "Our money"],
  "These words are also in the Quran, in Surah Az-Zukhruf.": "The travel dua of Muslim 1342, 'subhanal-ladhi sakhkhara lana hadha... wa inna ila Rabbina la-munqalibun', is Quran 43:13-14 in Az-Zukhruf.",
  "What does tahurun mean in this dua?": ["Bukhari 3616: he ﷺ visited a Bedouin and said 'la ba'sa, tahurun in sha Allah.' What does 'tahur' mean?", "A sleep", "A journey", "A punishment"],
  "When did he ﷺ say La ba'sa, tahurun in sha Allah?": ["Bukhari 3616: 'kana idha dakhala 'ala marid...' When did he ﷺ say 'la ba'sa, tahurun'?", "At a wedding", "When it rained", "At the market"],
  "Visiting the sick is part of the Prophet's ﷺ way.": "In Bukhari 3616 he ﷺ visited a sick Bedouin and said 'la ba'sa, tahurun in sha Allah': no harm, a cleansing if Allah wills.",
  "What word takes anger away, as the Prophet ﷺ said?": ["Bukhari 3282: two men insulted each other, one's face red. Which words did he ﷺ say would remove it?", "Shouting louder", "Alhamdulillah", "Nothing helps"],
  "What does A'udhu billah mean?": ["Bukhari 3282: 'law qala a'udhu billahi minash-shaytan, dhahaba 'anhu ma yajid.' What does a'udhu billah mean?", "Leave me alone", "Thank you", "I am the strongest"],
  "Anger can come from Shaytan.": "In Bukhari 3282 he ﷺ said that if the angry man said 'I seek refuge in Allah from Satan', what he felt would leave him.",
  "Which dua did the Prophet ﷺ make most often?": ["Bukhari 6389, from Anas: 'kana aktharu du'a'in-nabiyyi ﷺ...' Which dua?", "Rabbi zidni 'ilma", "The dua of travel", "The dua for rain"],
  "This dua also asks to be saved from the Fire.": "Bukhari 6389: his ﷺ most frequent dua was 'Rabbana atina fid-dunya hasanah wa fil-akhirati hasanah wa qina 'adhaban-nar'.",
  "What does Rabbi zidni 'ilma ask for?": ["Quran 20:114: 'wa la ta'jal bil-Qur'an... wa qul Rabbi zidni ____.' What is asked for?", "More games", "More sleep", "More food"],
  "A good time to say Rabbi zidni 'ilma is...": ["Quran 20:114: 'wa qul Rabbi zidni 'ilma.' You sit down to learn. When does this dua fit best?", "Only when sick", "Only at night", "Never out loud"],
  "Allah Himself taught this dua in the Quran.": "In Quran 20:114 Allah tells His Prophet ﷺ not to hasten with the Quran before its revelation is complete, and to say: my Lord, increase me in knowledge.",
  "What does the dua in 3:8 ask Allah to keep steady?": ["Quran 3:8: 'Rabbana la tuzigh ____ ba'da idh hadaytana.' What must not swerve?", "Our houses", "Our money", "The weather"],
  "After what should our hearts not swerve?": ["Quran 3:8: 'la tuzigh qulubana ba'da idh ____.' After what?", "After dinner", "After school", "After a holiday"],
  "The dua also asks Allah for mercy.": "Quran 3:8 asks 'wa hab lana min ladunka rahmah, innaka antal-Wahhab': grant us mercy from Yourself; You are the Giver.",
  "Who is the dua in 17:24 for?": ["Quran 17:24: 'Rabbir-hamhuma kama rabbayani saghira.' Who is the dua for?", "Your teacher", "Your friends", "Your neighbors"],
  "Why do we ask mercy for them?": ["Quran 17:24: 'kama rabbayani saghira.' Why do we ask mercy for them?", "They asked us to", "They are rich", "They are famous"],
  "The ayah also says to be humble with your parents.": "Quran 17:24 says 'wakhfid lahuma janahadh-dhulli minar-rahmah': lower to your parents the wing of humility out of mercy.",
  "What does 25:74 ask our families to be?": ["Quran 25:74: 'Rabbana hab lana min azwajina wa dhurriyyatina qurrata a'yun.' What do we ask our families to be?", "Rich and famous", "Far away", "Always quiet"],
  "Who makes this dua in Surah Al-Furqan?": ["Quran 25:74, in Al-Furqan: who are those who make this dua, as the surah names them?", "The hypocrites", "The angels only", "The people of Firawn"],
  "The dua asks to be leaders of the God-fearing.": "Quran 25:74 ends 'waj'alna lil-muttaqina imama': make us leaders for the righteous.",
  "Who first made the dua Rabbish-rah li sadri?": ["Quran 20:25: 'qala Rabbish-rah li sadri, wa yassir li amri.' Who said it?", "Yunus", "Adam", "Ibrahim"],
  "Where was Musa about to go?": ["Quran 20:24-25: told 'idh-hab ila Fir'awna innahu tagha', he asked for an open chest. Where was he sent?", "To Makkah", "To the market", "To sleep"],
  "A good time for this dua is before a hard talk or a test.": "Quran 20:25-28: 'wahlul 'uqdatan min lisani, yafqahu qawli', untie the knot from my tongue that they may understand, fits before a hard talk.",
  "Who said Rabbana zalamna anfusana?": ["Quran 7:23: 'qala Rabbana zalamna anfusana wa in lam taghfir lana.' Who said it?", "Musa and Harun", "The people of Ad", "Firawn and Haman"],
  "What did they admit?": ["Quran 7:23: 'wa in lam taghfir lana wa tarhamna la-nakunanna minal-khasirin.' What did they admit first?", "We want more fruit", "We did nothing wrong", "Shaytan is innocent"],
  "Saying sorry to Allah is the way of Adam.": "Quran 7:23 tells that Adam and Hawwa said 'we have wronged ourselves', and asked Allah to forgive them and have mercy.",
  "Where was Yunus when he made this dua?": ["Quran 21:87: 'fa-nada fiz-zulumat.' Where was Yunus when he called out?", "On a mountain", "In a palace", "In the market"],
  "What did Allah do after his dua?": ["Quran 21:87-88: 'fastajabna lahu wa najjaynahu minal-ghamm.' What did Allah do?", "Sent a storm", "Made him king", "Ignored him"],
  "Yunus admitted his own wrong in the dua.": "Quran 21:87 has Yunus say 'la ilaha illa anta subhanaka inni kuntu minaz-zalimin': indeed I have been of the wrongdoers.",
  "In what do hearts find rest, says 13:28?": ["Quran 13:28: 'ala bi-dhikrillahi tatma'innul-qulub.' In what do hearts find rest?", "Wealth", "Family", "Travel"],
  "You feel worried before an exam. What does this ayah point you to?": ["Quran 13:28: 'tatma'innul-qulub.' A worry sits on your heart before an exam. What does the ayah point to?", "Skipping prayer", "Giving up", "Shouting"],
  "Dhikr is only for the mosque.": "By Quran 13:28, hearts find rest in the remembrance of Allah only when it is done inside the mosque.",
  "What does Allah promise the one who remembers Him?": ["Quran 2:152: 'fadhkuruni ____.' What does Allah promise?", "Wealth", "A long life", "Ease from all tests"],
  "Allah remembers the one who remembers Him.": "Quran 2:152 says 'fadhkuruni adhkurkum washkuru li wa la takfurun': remember Me and I will remember you; be grateful and do not deny Me.",
  "The one who remembers Allah is like what?": ["Bukhari 6407, from Abu Musa: 'mathalul-ladhi yadhkuru Rabbahu wal-ladhi la yadhkuruh...' Like what?", "A sleeping person", "A dead person", "A lost person"],
  "And the one who never remembers Him?": ["Bukhari 6407: the one who remembers his Lord is like the living. The one who does not, like what?", "Like a teacher", "Like a king", "Like a bird"],
  "Dhikr keeps the heart alive.": "Bukhari 6407 likens the one who remembers his Lord and the one who does not to the living and the dead.",
  "Where are the two words heavy?": ["Bukhari 6406: 'kalimatani khafifatani 'alal-lisan, thaqilatani fil-____.' Where are they heavy?", "In your pocket", "In your bag", "Nowhere"],
  "Which pair are the two words?": ["Bukhari 6406: 'habibatani ilar-Rahman.' Which two words are these?", "Insha'Allah, Masha'Allah", "Bismillah, Amin", "Salam, Shukran"],
  "These words are loved by the Most Merciful.": "Bukhari 6406 calls the two words light on the tongue, heavy on the Scale, and beloved to the Most Merciful.",
  "How many words are most loved to Allah in this hadith?": ["Muslim 2137a: 'ahabbul-kalami ilallahi ____.' How many?", "Two", "Ten", "Seven"],
  "Which of these is one of them?": ["Muslim 2137a: subhanallah, al-hamdu lillah, la ilaha illallah, and which fourth?", "Good morning", "Thank you", "Well done"],
  "You must say them in one fixed order.": "By Muslim 2137a, the four dearest words to Allah lose their worth unless said in the order subhanallah, al-hamdu lillah, la ilaha illallah, Allahu akbar.",
  "Where do the words of dhikr go, he ﷺ said?": ["Ibn Majah 3809, from An-Nu'man: tasbih, tahlil and tahmid 'yan'atifna hawlal-'arsh.' Where do they go?", "Around the moon", "Across the seas", "Over the mountains"],
  "What do the words of dhikr hum like, he ﷺ said?": ["Ibn Majah 3809: 'lahunna dawiyyun ka-dawiyyin-nahl.' What do they hum like?", "Like birds", "Like the wind", "Like a river"],
  "The words of dhikr mention the one who said them.": "Ibn Majah 3809 says the words of glorifying Allah turn around the Throne, humming like bees, reminding of the one who said them.",
  "Why count dhikr on the fingers, he ﷺ said?": ["Abu Dawud 1501, from Yusayrah: ''qidna bil-anamil fa-innahunna mas'ulatun mustantaqat.' Why the fingers?", "They will grow much longer", "They will turn into gold", "They will feel much warmer"],
  "Whom did he ﷺ tell to count dhikr on their fingers?": ["Abu Dawud 1501: Yusayrah, an emigrant woman, told how he ﷺ taught them to count on their fingers. Whom did he tell?", "The Persian kings", "The Yemeni traders", "The desert poets"],
  "Counting dhikr on our fingers is a good way to count it.": "Abu Dawud 1501 teaches counting tasbih on the fingertips, because the fingers will be questioned and made to speak.",
  "La hawla wa la quwwata illa billah is a treasure of where?": ["Bukhari 6384: 'ya 'Abdallah ibn Qays, a-la adulluka 'ala kanzin min kunuz ____?' Treasure of where?", "The desert", "The ocean", "A king's palace"],
  "What does it mean?": ["Bukhari 6384: 'la hawla wa la quwwata illa billah.' What does it mean?", "I am strong alone", "Let us go home", "Peace be upon you"],
  "On that journey he ﷺ also said: Allah is not deaf or far away.": "In Bukhari 6384 they were raising their voices with takbir on a journey, and he ﷺ said: you are not calling one deaf or absent.",
  "Send one salawat on the Prophet ﷺ. How many blessings does Allah send you?": ["Muslim 408, from Abu Hurayrah: 'man salla 'alayya wahidatan salla Allahu 'alayhi ____.' How many?", "None", "One", "Two"],
  "Which words send salawat?": ["Muslim 408: 'man salla 'alayya wahidah.' Which words send that one blessing on him ﷺ?", "Astaghfirullah", "Amin", "Alhamdulillah"],
  "Writing ﷺ after his name is a short salawat.": "Writing ﷺ after his name is a short form of salawat, and by Muslim 408 Allah blesses ten times whoever sends one.",
  "How many times a day did the Prophet ﷺ ask forgiveness?": ["Muslim 2702a, from Al-Agharr: 'innahu la-yughanu 'ala qalbi, wa inni la-astaghfirullaha fil-yawm ____.' How many?", "Once", "Five", "Seven"],
  "Which word asks Allah for forgiveness?": ["Muslim 2702a: 'astaghfirullah fil-yawmi mi'ata marrah.' Which word is it?", "Masha'Allah", "Subhanallah", "Alhamdulillah"],
  "Only people with big sins need istighfar.": "By Muslim 2702a, asking forgiveness every day is only for those who have done big sins.",
  "What two feelings does this dua start with?": ["Bukhari 6369: 'Allahumma inni a'udhu bika minal-____ wal-____.' Which two begin it?", "Joy and fun", "Hunger and thirst", "Heat and cold"],
  "Which of these does it also seek refuge from?": ["Bukhari 6369: worry, grief, 'wal-'ajzi wal-____.' Which one comes next?", "Prayer", "Reading", "Kindness"],
  "The Prophet ﷺ used to say this dua himself.": "In Bukhari 6369, from Anas, the Prophet ﷺ used to say: I seek refuge in You from worry, grief, weakness, laziness, miserliness, cowardice, debt and being overpowered.",
  "When did the Prophet ﷺ say this dhikr?": ["Bukhari 6346: 'la ilaha illallahul-'Azimul-Halim.' 'Inda al-karb': when did he ﷺ say it?", "On Eid only", "At weddings", "When eating"],
  "Allah is called Lord of what in it?": ["Bukhari 6346: 'Rabbus-samawati wal-ard, wa Rabbul-'arshil-____.' Lord of what?", "The palace", "The ships", "The market"],
  "In hard times he ﷺ turned to praising Allah.": "In Bukhari 6346 he ﷺ said in distress: none has the right to be worshipped but Allah, the Mighty, the Forbearing, Lord of the Mighty Throne.",
  "What did Ibrahim ask for himself and his children?": ["Quran 14:40: 'Rabbij'alni ____ wa min dhurriyyati.' What did Ibrahim ask?", "To be rich", "To be famous", "To be kings"],
  "Whom did Ibrahim include in his du'a?": ["Quran 14:40: 'Rabbij'alni muqimas-salati wa min ____.' Whom did he add?", "Only his friends", "No one", "Only himself"],
  "Ibrahim ended by asking Allah to accept his du'a.": "Quran 14:40 ends Ibrahim's dua with 'Rabbana wa taqabbal du'a': our Lord, accept my supplication.",
  "Whom did Nuh ask forgiveness for right after himself?": ["Quran 71:28: 'Rabbighfir li wa li-____.' Whom did Nuh name after himself?", "His enemies", "Only his ship", "No one"],
  "Who else is in Nuh's du'a?": ["Quran 71:28: 'wa li-man dakhala bayti mu'minan wa lil-____.' Whom does it end with?", "Only animals", "Only kings", "Only his crew"],
  "We can make du'a for all the believers, not only ourselves.": "In Quran 71:28 Nuh asks forgiveness for himself, his parents, whoever enters his house a believer, and all believing men and women.",
  "What did Zakariyya ask Allah not to do?": ["Quran 21:89: 'Rabbi la tadharni fardan wa anta khayrul-warithin.' What did Zakariyya ask?", "Send him far", "Make him rich", "Give him rain"],
  "Which son did Allah give Zakariyya?": ["Quran 21:90: 'fastajabna lahu wa wahabna lahu ____.' Which son?", "Harun", "Ishaq", "Yusuf"],
  "Zakariyya was very old, yet he still asked Allah.": "Zakariyya, whose dua in Quran 21:89 ends 'You are the best of inheritors', was very old and still asked his Lord.",
  "What did Ayyub tell Allah in his du'a?": ["Quran 21:83: 'anni massaniyad-durr.' What did Ayyub say to his Lord?", "I am angry", "Nothing at all", "I give up"],
  "How did Ayyub describe Allah?": ["Quran 21:83: 'wa anta ____.' How did Ayyub name Allah?", "The far away", "The one who forgets", "The one who is tired"],
  "Ayyub complained to Allah, not to people.": "In Quran 21:83 Ayyub told his Lord 'harm has touched me, and You are the Most Merciful of the merciful', taking his complaint to Allah alone.",
  "What made Sulayman smile before his du'a?": ["Quran 27:19: 'fa-tabassama dahikan min qawliha.' Whose words made Sulayman smile?", "A joke from a bird", "A gift of gold", "A song"],
  "What did Sulayman ask Allah to help him be?": ["Quran 27:19: 'Rabbi awzi'ni an ____ ni'matakal-lati an'amta 'alayy.' What did he ask to be?", "Famous", "Feared", "Lazy"],
  "Sulayman thanked Allah for blessings on his parents too.": "Quran 27:19 has Sulayman ask to be grateful for the favour on him and on his parents, and to do good that pleases Allah.",
  "How did Yusuf ask to leave this world?": ["Quran 12:101: 'tawaffani ____ wa alhiqni bis-salihin.' How did Yusuf ask to die?", "As a rich man", "As a famous man", "As a king"],
  "Whom did Yusuf ask to be joined with?": ["Quran 12:101: 'tawaffani musliman wa alhiqni bi-____.' Joined with whom?", "The kings", "The traders", "The soldiers"],
  "Yusuf said his du'a when Allah had given him power and his family back.": "Quran 12:101 opens 'Rabbi qad ataytani minal-mulk': Yusuf made this dua after Allah gave him power and brought his family back.",
  "What did Ibrahim and Isma'il ask Allah to make them?": ["Quran 2:128: 'Rabbana waj'alna ____ lak.' What did Ibrahim and Isma'il ask to be?", "Owners of much gold", "Leaders of great armies", "Kings of the earth"],
  "Whom else did they ask Allah to make a Muslim nation?": ["Quran 2:128: 'wa min dhurriyyatina ummatan muslimatan lak.' Whom did they add?", "Their hired workers", "Their travel companions", "Their honored guests"],
  "They also asked Allah to show them their rites of worship.": "In Quran 2:128 Ibrahim and Isma'il ask 'wa arina manasikana wa tub 'alayna': show us our rites and accept our repentance.",
  "What did Ibrahim ask Allah to make Makkah?": ["Quran 14:35: 'Rabbij'al hadhal-balada ____.' What for Makkah?", "A city of kings", "A city by the sea", "A city of towers"],
  "Whom did Ibrahim include with himself in this du'a?": ["Quran 14:35: 'wajnubni wa baniyya an na'budal-asnam.' Whom did he include?", "His guests", "His neighbors", "His helpers"],
  "Ibrahim asked Allah to keep him away from worshipping idols.": "Quran 14:35 has Ibrahim ask 'wajnubni wa baniyya an na'budal-asnam': keep me and my sons away from worshipping idols.",
  "What did Ibrahim ask his Lord to grant him?": ["Quran 37:100: 'Rabbi hab li minas-salihin.' What was Ibrahim asking for?", "A grand palace", "An army", "A treasure"],
  "Which words begin Ibrahim's du'a for a child?": ["Quran 37:100-101: he asked, then 'fa-bashsharnahu bi-ghulamin halim'. Which words began his dua?", "Rabbana atina", "Rabbi zidni", "Rabbana la tuzigh"],
  "Ibrahim asked for a child who would be righteous.": "In Quran 37:100 Ibrahim asked 'Rabbi hab li minas-salihin', and Allah gave him glad tidings of a forbearing boy.",
  "What did Musa ask Allah to save him from?": ["Quran 28:21: 'Rabbi najjini minal-____.' Saved from whom?", "The desert heat", "The wild beasts", "The long road"],
  "How did Musa feel as he left the city?": ["Quran 28:21: 'fa-kharaja minha kha'ifan yataraqqab.' How did Musa leave?", "Full and sleepy", "Calm and rested", "Happy and relaxed"],
  "When Musa was afraid, he turned to his Lord.": "Quran 28:21 tells that Musa left the city afraid and on his guard, and said: my Lord, save me from the wrongdoing people.",
  "What did Nuh seek refuge from?": ["Quran 11:47: 'Rabbi inni a'udhu bika an as'alaka ma laysa li bihi 'ilm.' Refuge from what?", "Asking for a big house", "Asking for more gold", "Asking for a long rest"],
  "Without Allah's forgiveness and mercy, Nuh said he would be among whom?": ["Quran 11:47: 'wa illa taghfir li wa tarhamni akun minal-____.' Among whom?", "The kings", "The rich", "The strong"],
  "Nuh asked Allah to forgive him and have mercy on him.": "In Quran 11:47 Nuh sought refuge from asking what he had no knowledge of, and asked his Lord to forgive him and have mercy on him.",
  "What did Nuh say his people had done to him?": ["Quran 23:26: 'Rabbin-surni bima ____.' Because of what?", "Crowned him", "Paid him", "Honored him"],
  "Which words begin Nuh's du'a in Quran 23:26?": ["Quran 23:26-27: after the dua, 'fa-awhayna ilayhi anis-na'il-fulk.' Which words began it?", "Rabbi hab li", "Rabbana atina", "Rabbi zidni"],
  "Nuh turned to his Lord when his people denied him.": "In Quran 23:26 Nuh said 'Rabbin-surni bima kadhdhabun', and Allah then told him to build the ship.",
  "Along with himself, whom did Nuh ask Allah to save?": ["Quran 26:118: 'wa najjini wa man ma'iya minal-____.' Whom else did Nuh ask to be saved?", "The chiefs of his people", "The rich of his people", "The strong of his people"],
  "How did Nuh ask Allah to judge between him and them?": ["Quran 26:118: 'faftah bayni wa baynahum ____.' How?", "Slowly", "Secretly", "Gently"],
  "Before this du'a, Nuh said that his people had denied him.": "In Quran 26:117-118 Nuh said 'my people have denied me', asked Allah to judge decisively, and Allah saved them in the laden ship.",
  "Where did the youths shelter before their du'a?": ["Quran 18:10: 'idh awal-fityatu ilal-____.' Where did the youths shelter?", "In a palace", "On a ship", "In a market"],
  "What did they ask for?": ["Quran 18:10: 'atina min ladunka rahmatan wa hayyi' lana min amrina rashada.' What did they ask?", "Gold and silver", "An army", "Fame"],
  "The youths of the cave were young people who held on to faith.": "Quran 18:10 calls the people of the cave 'al-fityah', the youths, who sheltered there and asked their Lord for mercy and right guidance.",
  "Whom do we ask forgiveness for in Quran 59:10?": ["Quran 59:10: 'Rabbanaghfir lana wa li-ikhwaninal-ladhina sabaquna bil-iman.' For whom?", "No one", "Only ourselves", "Only the rich"],
  "What do we ask Allah to keep out of our hearts?": ["Quran 59:10: 'wa la taj'al fi qulubina ghillan lil-ladhina amanu.' Keep what out?", "Love", "Mercy", "Hope"],
  "Quran 59:10 teaches us to love the believers who came before us.": "Quran 59:10 has us pray for the brothers who came before us in faith and ask for no resentment in our hearts toward the believers.",
  "At what age does the believer make the du'a of Quran 46:15?": ["Quran 46:15: 'hatta idha balagha ashuddahu wa balagha ____ sanah.' At what age?", "Ten years", "Ninety years", "One year"],
  "Who else is blessed in the du'a?": ["Quran 46:15: thanks for favour 'alayya wa 'ala walidayya', and 'aslih li fi dhurriyyati'. For whom?", "Only his boss", "Only strangers", "No one"],
  "In the du'a we ask to do good that pleases Allah.": "Quran 46:15: 'wa an a'mala salihan tardah': the believer asks to do good that pleases Allah.",
  "Who said the du'a of Quran 7:126?": ["Quran 7:126: 'wa ma tanqimu minna illa an amanna bi-ayati Rabbina.' Who said this to Fir'awn?", "The soldiers of Fir'awn", "The traders of Madyan", "The people of Ad"],
  "What did they ask Allah to pour on them?": ["Quran 7:126: 'Rabbana afrigh 'alayna ____.' Pour what?", "Gold", "Fame", "Rain"],
  "They asked to die as Muslims.": "Quran 7:126 ends the believing magicians' dua 'wa tawaffana muslimin': let us die as Muslims.",
  "What did the believers ask Allah to make firm?": ["Quran 3:147: 'wa thabbit ____ wansurna.' Make what firm?", "Their swords", "Their walls", "Their houses"],
  "What did they ask for first?": ["Quran 3:147: 'Rabbanaghfir lana dhunubana wa israfana fi amrina.' What came first?", "Money", "Revenge", "A rest"],
  "In hard times, the believers asked Allah for help.": "Quran 3:147 says the believers who fought with the prophets asked only for forgiveness, firm feet, and help against the disbelievers.",
  "What does the du'a of Quran 23:118 ask for?": ["Quran 23:118: 'wa qur Rabbighfir warham.' What does it ask?", "Good weather", "A long trip", "A big house"],
  "How does the du'a describe Allah?": ["Quran 23:118: 'wa anta ____.' How is Allah named?", "The far away", "The silent", "The strictest judge"],
  "Quran 23:118 is the last ayah of Surah Al-Mu'minun.": "Quran 23:118, 'Rabbighfir warham wa anta khayrur-rahimin', is the last ayah of Surah Al-Mu'minun.",
  "What do they tell Allah before asking to be forgiven?": ["Quran 3:16: 'Rabbana innana ____ faghfir lana dhunubana.' What do they say first?", "We have grown rich", "We have built a house", "We have traveled far"],
  "What do they ask Allah to protect them from?": ["Quran 3:16: 'wa qina 'adhaban-nar.' Protect from what?", "A poor harvest", "A long winter", "A hard journey"],
  "They ask Allah to forgive their sins.": "Quran 3:16 says the believers say 'we have believed', then ask Allah to forgive their sins and guard them from the Fire.",
  "Whom did the disciples say they followed?": ["Quran 3:53: 'amanna bima anzalta wattaba'nar-rasul.' Whom did the disciples follow?", "The king's guards", "The rich men", "The old poets"],
  "Among whom did they ask Allah to write them?": ["Quran 3:53: 'faktubna ma'ash-____.' Among whom?", "The kings", "The poets", "The rulers"],
  "The disciples believed in what Allah revealed.": "Quran 3:53 has the disciples of Isa say 'amanna bima anzalta': we believed in what You revealed and followed the messenger.",
  "What do they do with the creation of the heavens and the earth?": ["Quran 3:191: 'wa yatafakkaruna fi khalqis-samawati wal-ard.' What do they do with creation?", "Make fun of it", "Turn away from it", "Worship it"],
  "Which du'a do they make after thinking about creation?": ["Quran 3:191: after reflecting, 'Rabbana ma khalaqta hadha ____.' What do they say?", "Make us kings of the land", "Let us live here forever", "Give us more of this world"],
  "They remember Allah standing, sitting and lying on their sides.": "Quran 3:191 says they remember Allah 'qiyaman wa qu'udan wa 'ala junubihim': standing, sitting and on their sides.",
  "Who make this du'a, in Surah Al-Furqan?": ["Quran 25:65: 'Rabbanasrif 'anna 'adhaba jahannam.' In Al-Furqan, who says it?", "The people of Nuh", "The people of Ad", "The people of Lut"],
  "What do they say about Hell's punishment?": ["Quran 25:65: 'inna 'adhabaha kana gharama.' What is said of it?", "It is light", "It is easy", "It soon ends"],
  "The servants of the Most Merciful ask Allah to keep Hell away from them.": "Quran 25:65 has the servants of the Most Merciful ask Allah to turn the punishment of Hell away, for its punishment never lets go.",
  "What will the believers ask Allah to perfect for them?": ["Quran 66:8: 'Rabbana atmim lana ____.' Perfect what?", "Their wealth", "Their farms", "Their clothes"],
  "What do the believers ask for along with their light?": ["Quran 66:8: 'atmim lana nurana waghfir lana.' What comes with the light?", "Power", "Wealth", "A long life"],
  "The believers will say this du'a while their light runs before them.": "Quran 66:8 says on that Day the believers' light runs before them and on their right, and they say: our Lord, perfect our light.",
  "Whom will Allah gather for that Day, says Quran 3:9?": ["Quran 3:9: 'Rabbana innaka jami'un-nas.' Whom will He gather?", "Only the kings", "Only the prophets", "Only the scholars"],
  "What does the du'a say about that Day?": ["Quran 3:9: 'li-yawmin la rayba fih.' What of that Day?", "It is only a dream", "It is far away", "It may never come"],
  "This du'a says that Allah never breaks His promise.": "Quran 3:9 ends 'innallaha la yukhliful-mi'ad': Allah does not fail in His promise.",
  "What happens to those Allah puts in the Fire, says Quran 3:192?": ["Quran 3:192: 'man tudkhilin-nara faqad ____.' What happens to them?", "They are rewarded", "They are thanked", "They are honored"],
  "Who will have no helpers, says the du'a?": ["Quran 3:192: 'wa ma lidh-dhalimina min ansar.' Who have no helpers?", "The God-fearing", "The righteous", "The humble"],
  "Just before this du'a, they ask Allah to protect them from the Fire.": "Quran 3:192 follows 3:191, where they say 'subhanaka fa-qina 'adhaban-nar', asking to be guarded from the Fire.",
  "What did the caller say, in Quran 3:193?": ["Quran 3:193: 'munadiyan yunadi lil-iman an aminu bi-Rabbikum.' What did he call?", "Rest in your homes", "Gather your wealth", "Build your houses"],
  "What did they ask Allah to remove from them?": ["Quran 3:193: 'faghfir lana dhunubana wa kaffir 'anna ____.' Remove what?", "Their debts", "Their poverty", "Their hunger"],
  "When they heard the call to faith, they believed.": "Quran 3:193 says they heard the caller to faith and believed, and asked to die with the righteous.",
  "When is the du'a of Quran 7:47 said?": ["Quran 7:47: 'wa idha surifat absaruhum tilqa'a ashabin-nar.' When is the dua said?", "When they see the new moon", "When they see the rain", "When they see the sea"],
  "Which words begin the du'a of Quran 7:47?": ["Quran 7:47: 'Rabbana la taj'alna ma'al-qawmiz-zalimin.' Which words begin it?", "Rabbana atina", "Rabbi zidni", "Rabbi hab li"],
  "They ask Allah not to place them with the wrongdoing people.": "Quran 7:47 says that when their eyes are turned toward the people of the Fire, they ask: do not place us with the wrongdoing people.",
  "Who made the du'a of Quran 26:87?": ["Quran 26:87: 'wa la tukhzini yawma yub'athun.' Who said it, ending his dua of 26:83-87?", "Nuh", "Musa", "Yunus"],
  "What did Ibrahim ask to be kept from on that Day?": ["Quran 26:87: 'wa la ____ yawma yub'athun.' Kept from what?", "Starve", "Freeze", "Tire"],
  "Ibrahim asked this for the Day when all people are resurrected.": "Quran 26:87 closes Ibrahim's dua of 26:83-87: do not disgrace me on the Day all are resurrected.",
  "What happens when a believer makes du'a?": ["Tirmidhi 3381: 'illa atahullahu ma sa'ala aw kaffa 'anhu minas-su'i mithlah.' What happens to a dua?", "Nothing happens", "Only long du'as count", "Only rich people are answered"],
  "Which du'a did he ﷺ say is not answered?": ["Tirmidhi 3381: 'ma lam yad'u bi-ithmin aw qati'ati rahim.' Which dua is not answered?", "A du'a for health", "A du'a for parents", "A du'a for rain"],
  "A du'a can be answered by keeping a harm away from you.": "Tirmidhi 3381 says Allah gives what was asked or turns away an equal harm, as long as one does not ask for a sin or cutting family ties.",
  "When should we make much du'a, to be answered in hard times?": ["Tirmidhi 3382: 'man sarrahu an yastajiballahu lahu 'indash-shada'id...' When to make much dua?", "Only once a year", "Only when sick", "Only in hard times"],
  "What two hard times did he ﷺ name?": ["Tirmidhi 3382: 'indash-shada'idi wal-karb.' Which two hard times?", "Meals and sleep", "Trips and holidays", "Mornings and evenings"],
  "We should turn to Allah only when things go wrong.": "By Tirmidhi 3382, there is no need to make du'a in good times, since Allah answers best in hardship.",
  "What did he ﷺ say about hands raised to Allah in du'a?": ["Tirmidhi 3556: 'innallaha hayiyyun karim, yastahyi idha rafa'ar-rajulu ilayhi yadayh...' What does He not do?", "They must be washed first", "They must stay up an hour", "They must be raised very high"],
  "Which name of Allah is in the hadith of raised hands?": ["Tirmidhi 3556: 'innallaha hayiyyun ____.' Which name of His is in the hadith?", "Al-Malik, the King", "Al-Qawiyy, the Strong", "Al-Alim, the All-Knowing"],
  "Raising your hands is part of making du'a.": "Tirmidhi 3556 says Allah is shy and generous, too shy to send back empty the hands a man raises to Him.",
  "Whom did he ﷺ begin with, when making du'a for someone?": ["Tirmidhi 3385, from Ubayy: 'kana idha dhakara ahadan fa-da'a lahu bada'a bi-____.' With whom?", "With the oldest person there", "With the person he named", "With the people around him"],
  "Who told how he ﷺ began his du'a for others?": ["Tirmidhi 3385: 'bada'a bi-nafsih.' Which Companion reported this of him ﷺ?", "Bilal", "Abu Hurairah", "Abu Bakr"],
  "You can ask Allah for yourself and for others in one du'a.": "Tirmidhi 3385 says that when he ﷺ mentioned someone and made dua for him, he began with himself.",
  "When is the Lord closest to His servant?": ["Tirmidhi 3579, from Amr ibn Abasah: 'aqrabu ma yakunur-Rabbu minal-'abdi fi jawfil-layl...' When?", "At sunset", "Right after lunch", "At noon"],
  "What did he ﷺ say to do in the last part of the night?": ["Tirmidhi 3579: 'fa-inistata'ta an takuna mimman yadhkurullaha fi tilkas-sa'ah.' Do what?", "Talk with friends", "Go to the market", "Eat a big meal"],
  "The last part of the night is a special time to remember Allah.": "Tirmidhi 3579 says the Lord is closest to the servant in the last part of the night, so be among those who remember Allah then.",
  "What did he ﷺ call the best dhikr?": ["Tirmidhi 3383: 'afdaludh-dhikri ____.' Which is the best dhikr?", "Allahu Akbar", "Astaghfirullah", "Subhan Allah"],
  "What did he ﷺ call the best du'a?": ["Tirmidhi 3383: 'wa afdalud-du'a'i ____.' Which is the best dua?", "Amin", "Bismillah", "Insha'Allah"],
  "La ilaha illallah means none is worshipped but Allah.": "Tirmidhi 3383 says the best dhikr is la ilaha illallah, none worthy of worship but Allah, and the best dua is al-hamdu lillah.",
  "To whom do we entrust a traveler's religion?": ["Tirmidhi 3443: 'astawdi'ullaha dinaka wa amanataka wa khawatima 'amalik.' To whom is the religion entrusted?", "To the captain", "To his bags", "To his friends"],
  "What three things did he ﷺ entrust to Allah?": ["Tirmidhi 3443: 'dinaka wa amanataka wa khawatima 'amalik.' Which three?", "Shoes, bags and water", "Money, food and clothes", "House, camel and tent"],
  "Ibn Umar said goodbye the way the Prophet ﷺ said goodbye.": "In Tirmidhi 3443 Ibn Umar said 'come near so I bid you farewell as the Messenger of Allah ﷺ bid us farewell'.",
  "What provision did he ﷺ give the traveler first?": ["Tirmidhi 3444: 'ya Rasulallah, zawwidni.' He ﷺ said 'zawwadakallahu ____.' What first?", "Water", "Money", "Dates"],
  "What did he ﷺ add when the man asked for more?": ["Tirmidhi 3444: 'zidni.' He ﷺ said 'wa ghafara ____.' What next?", "May you be famous", "May you get rich", "May you travel fast"],
  "He ﷺ prayed that good would be made easy for the traveler.": "In Tirmidhi 3444 he ﷺ gave the traveler taqwa, forgiveness of sin, and 'yassara lakal-khayra haythuma kunt', good made easy wherever he is.",
  "What did he ﷺ tell the traveler to say on high places?": ["Tirmidhi 3445: ''alayka bi-taqwallah, wat-takbiri 'ala kulli sharaf.' What on every high place?", "Amin", "Subhan Allah", "Bismillah"],
  "What did he ﷺ ask Allah for the traveler?": ["Tirmidhi 3445: 'Allahummatwi lahul-bu'da wa hawwin 'alayhis-safar.' What did he ﷺ ask?", "A fast camel", "A big tent", "Good weather"],
  "The first advice to the traveler was the taqwa of Allah.": "In Tirmidhi 3445 a man about to travel asked for advice, and he ﷺ said first: hold to the taqwa of Allah, and say takbir on every high place.",
  "In the travel du'a, who looks after the family left behind?": ["Tirmidhi 3438: 'antas-sahibu fis-safar wal-khalifatu fil-ahl.' Who looks after the family?", "Nobody at all", "The neighbors", "The guards"],
  "When did he ﷺ say: O Allah, You are the companion on the journey?": ["Tirmidhi 3438: 'Allahumma antas-sahibu fis-safar.' When did he ﷺ say it?", "When he reached Makkah", "When he went to sleep", "When he ate dinner"],
  "In the travel du'a, he ﷺ asked Allah to bring them back safely.": "In Tirmidhi 3438 he ﷺ asked Allah to be their companion on the road and bring them back to their families safe.",
  "When did he ﷺ say Ayibuna ta'ibuna?": ["Tirmidhi 3440: 'ayibuna ta'ibuna 'abiduna li-Rabbina hamidun.' When did he ﷺ say it?", "Setting out on a journey", "Waking up in the morning", "Finishing a meal"],
  "What do the words Ayibuna ta'ibuna mean?": ["Tirmidhi 3440: 'ayibuna ta'ibuna.' What do these two words mean?", "Welcome, welcome", "Goodbye, goodbye", "Hurry, hurry"],
  "Coming home, he ﷺ said words of praise for his Lord.": "Tirmidhi 3440 says that coming home from a journey he ﷺ said: returning, repenting, worshipping, and praising our Lord.",
  "Why did the people come to him ﷺ weeping?": ["Abu Dawud 1169, from Jabir: 'atat an-nabiyya ﷺ bawakin.' Why weeping?", "A war had begun", "A flood had come", "A guest had left"],
  "What kind of rain did he ﷺ ask Allah for?": ["Abu Dawud 1169: 'ghaythan mughithan mari'an... nafi'an ghayra darr.' What rain did he ﷺ ask for?", "Rain for one hour", "Rain only on the sea", "Rain only at night"],
  "After his du'a, clouds covered the sky.": "Abu Dawud 1169 says that after his ﷺ dua for rain, 'fa-atbaqat 'alayhimus-sama'': the sky closed over them with clouds.",
  "Why would there be famine despite heavy rain, he ﷺ said?": ["Muslim 2904: 'laysatis-sanatu bi-an la tumtaru... wa la tunbitul-ardu shay'a.' Why famine with rain?", "No river would flow", "No cloud would form", "No wind would blow"],
  "Famine comes only when no rain falls.": "By Muslim 2904, famine is simply a year with no rain; when heavy rain falls there is no famine.",
  "Who reported his ﷺ words on famine despite heavy rain?": ["Muslim 2904: 'laysatis-sanatu bi-an la tumtaru.' Which Companion narrated it?", "Jabir ibn Abdullah", "Anas ibn Malik", "Ibn Umar"],
  "When did the man ask him ﷺ to pray for rain?": ["Bukhari 1013, from Anas: a man came in 'wa Rasulullahi ﷺ qa'imun yakhtub'. When?", "At the Eid prayer", "At night in the market", "On a journey"],
  "What did he ﷺ say when the rain had to stop?": ["Bukhari 1013: a week of rain, then 'Allahumma hawalayna wa la 'alayna.' What does it ask?", "Rain only at night", "Rain only on Fridays", "Rain only on the sea"],
  "After the second du'a, they walked out in the sun.": "In Bukhari 1013 the rain fell from one Friday to the next, and after his ﷺ second dua it stopped and they walked out in the sun.",
  "What had the people complained of to him ﷺ?": ["Abu Dawud 1173, from Aishah: 'shakan-nasu ila Rasulillahi ﷺ quhutal-matar.' What had they complained of?", "Too much rain", "A cold winter", "Prices in the market"],
  "In his du'a, what did he ﷺ call the people?": ["Abu Dawud 1173: 'antal-Ghaniyyu wa nahnul-____.' What did he ﷺ call them?", "The strong", "The kings", "The rich"],
  "He ﷺ laughed when he saw people hurrying to shelter.": "In Abu Dawud 1173, when the rain came and he ﷺ saw them hurrying to shelter, he laughed until his molar teeth showed.",
  "What did he ﷺ do when the rain began?": ["Abu Dawud 5100, from Anas: 'fa-hasara thawbahu hatta asabahu minal-matar.' What did he ﷺ do?", "Ran inside at once", "Covered his head", "Waited under a tree"],
  "Why did he ﷺ want the rain on him?": ["Abu Dawud 5100: 'li-annahu hadithu 'ahdin bi-Rabbih.' Why?", "To cool off in the heat", "To wash his clothes", "To show it was strong"],
  "He ﷺ hurried indoors to stay dry from the rain.": "In Abu Dawud 5100 he ﷺ pulled his garment over himself so that none of the rain would touch him.",
  "Where does the wind come from, he ﷺ said?": ["Abu Dawud 5097: 'ar-rihu min rawhillah, ta'ti bir-rahmah wa ta'ti bil-'adhab.' From what?", "From the mountains", "From the angry sea", "From the stars"],
  "What should you do when a strong wind blows?": ["Abu Dawud 5097: 'fa-la tasubbuha, wa salullaha khayraha.' A strong wind blows. What do you do?", "Blame the weather", "Hide and say nothing", "Curse the wind"],
  "Cursing the wind is fine when it blows hard.": "By Abu Dawud 5097, when the wind brings punishment and not mercy, it may be cursed.",
  "How did he ﷺ begin the du'a for new clothes?": ["Abu Dawud 4020: 'kana idhastajadda thawban... yaqul: Allahumma ____.' How did he ﷺ begin?", "O Allah, make it last", "Peace be on you", "O Allah, forgive me"],
  "What did he ﷺ ask Allah for, about the new garment?": ["Abu Dawud 4020: 'as'aluka khayrahu wa khayra ma suni'a lah.' What did he ﷺ ask for?", "That people praise it", "More clothes like it", "That it never tears"],
  "He ﷺ also sought refuge from the garment's evil.": "In Abu Dawud 4020 he ﷺ named the new garment, praised Allah for it, and sought refuge from its evil and the evil it was made for.",
  "How many times did he ﷺ say each phrase on waking?": ["Abu Dawud 5085: on waking at night, takbir, tahmid, tasbih, tahlil and istighfar, how many times each?", "Once each", "Three times each", "A hundred times each"],
  "From what did he ﷺ seek refuge, ten times, before praying?": ["Abu Dawud 5085: 'a'udhu billahi min diqil-maqami yawmal-qiyamah.' Refuge from what?", "The cold of the night", "Hunger and thirst", "Scary dreams"],
  "Aishah said many people had asked her the same before.": "In Abu Dawud 5085 Aishah said many people had already asked her about how he ﷺ began the night prayer.",
  "What should you do when dogs bark at night?": ["Abu Dawud 5103: 'idha sami'tum nubahal-kilab... fa-ta'awwadhu billah.' What should you do?", "Shout back at them", "Throw stones at them", "Run out of the house"],
  "Why should you seek refuge then, he ﷺ said?": ["Abu Dawud 5103: 'fa-innahunna yarayna ma la tarawn.' Why?", "They want some food", "They feel the cold air", "They want to play"],
  "Seek refuge in Allah when donkeys bray at night, too.": "Abu Dawud 5103 says to seek refuge in Allah on hearing dogs bark and donkeys bray at night, for they see what you do not.",
  "At what time did he ﷺ say the journey du'a?": ["Abu Dawud 5086: on a journey 'wa ashar', he ﷺ said 'sami'a sami'un bi-hamdillah'. When?", "At noon", "At sunset", "At midnight"],
  "What did he ﷺ ask the Lord to do for them?": ["Abu Dawud 5086: 'Rabbana sahibna wa afdil 'alayna.' What did he ﷺ ask?", "Make the road short", "Send them rain", "Give them gold"],
  "He ﷺ ended the journey du'a by seeking refuge from the Fire.": "Abu Dawud 5086 ends his ﷺ dawn dua on a journey with 'a'idhan billahi minan-nar', seeking refuge in Allah from the Fire.",
  "What should come first when you make du'a, he ﷺ said?": ["Abu Dawud 1481, from Fadalah: 'fal-yabda' bi-tahmidi Rabbihi wath-thana'i 'alayh.' What comes first?", "Asking for money", "Raising your voice", "Naming your needs"],
  "What comes after praise, before you ask for what you wish?": ["Abu Dawud 1481: 'thumma yusalli 'alan-nabiyy ﷺ, thumma yad'u.' What comes between praise and asking?", "A long silence", "Counting to ten", "Standing up straight"],
  "He ﷺ praised the man who rushed into his du'a.": "In Abu Dawud 1481 he ﷺ praised the man who made dua right away without praising Allah or sending blessings first.",
  "Whom did Abu Bakrah's son learn the du'a from?": ["Tirmidhi 3503: the son said it, and was asked 'mimman sami'taha?' From whom did he learn it?", "His uncle", "His teacher", "A traveller"],
  "From what three things does the du'a seek refuge?": ["Tirmidhi 3503: 'minal-hammi wal-kasali wa 'adhabil-qabr.' Which three?", "Hunger, thirst, the heat", "Noise, dust, the dark", "Rain, wind, the cold"],
  "Abu Bakrah told his son to stop saying the du'a.": "In Tirmidhi 3503 Abu Bakrah told his son to stop saying these words, since they were not from the Prophet ﷺ.",
  "With what did he ﷺ ask Allah to wash away sins?": ["Bukhari 6368, from Aishah: 'waghsil khatayaya bi-ma'ith-thalji wal-barad.' With what?", "Water of the sea", "Warm milk", "Rose water"],
  "How far from sins did he ﷺ ask Allah to put him?": ["Bukhari 6368: 'wa ba'id bayni wa bayna khatayaya kama ba'adta baynal-____.' How far?", "One step away", "Behind a small wall", "Across the street"],
  "He ﷺ sought refuge from the trial of poverty.": "In Bukhari 6368 he ﷺ sought refuge from the trial of the grave, the trial of the Fire, and the evil of the trial of wealth and of poverty.",
  "What did he ﷺ tell us to do about severe calamities?": ["Bukhari 6616: 'ta'awwadhu billahi min jahdil-bala'.' What did he ﷺ say to do?", "Give up hope", "Run and hide", "Blame other people"],
  "Which of these did he ﷺ tell us to seek refuge from?": ["Bukhari 6616: 'jahdil-bala', darakish-shaqa', su'il-qada', shamatatil-a'da'.' Which here is on the list?", "A long life", "A big family", "A kind neighbor"],
  "We may ask Allah to keep us from the gloating of enemies.": "Bukhari 6616 lists four to seek refuge from: hard trials, being overtaken by misery, a bad decree, and the gloating of enemies.",
  "What three things did he ﷺ seek refuge from first?": ["Abu Dawud 1544: 'a'udhu bika minal-faqri wal-qillati wadh-dhillah.' Which three first?", "Guests, gifts and food", "Rain, wind and cold", "Work, study and play"],
  "What else did he ﷺ ask Allah to keep him from?": ["Abu Dawud 1544: 'wa a'udhu bika an azlima aw uzlam.' What else?", "Eating too little", "Walking too far", "Speaking too softly"],
  "He ﷺ sought refuge from wronging others, and from being wronged.": "Abu Dawud 1544: 'an azlima aw uzlam': he ﷺ sought refuge from doing wrong and from being wronged.",
  "Which danger at home did he ﷺ seek refuge from?": ["Abu Dawud 1552: 'minal-hadmi wa a'udhu bika minat-taraddi.' Which danger at home?", "A noisy neighbor", "A dusty floor", "A broken cup"],
  "Which of these is also in his ﷺ du'a?": ["Abu Dawud 1552: 'minal-gharaqi wal-hariqi wal-haram.' Which two of these are in it?", "Laughing and smiling", "Running and jumping", "Eating and drinking"],
  "He ﷺ sought refuge from the devil harming him at death.": "Abu Dawud 1552: 'an yatakhabbatanish-shaytanu 'indal-mawt': he ﷺ sought refuge from the devil harming him at death.",
  "Which three bad things did he ﷺ seek refuge from?": ["Tirmidhi 3591: 'munkaratil-akhlaqi wal-a'mali wal-ahwa'.' Which three?", "Noise, dust and smoke", "Rain, wind and storms", "Hunger, thirst and heat"],
  "Who passed on the du'a from his uncle?": ["Tirmidhi 3591: told by Qutbah ibn Malik. Who, his nephew, passed it on?", "Anas ibn Malik", "Abu Hurairah", "Ibn Abbas"],
  "He ﷺ asked Allah to protect him from bad character.": "Tirmidhi 3591: 'Allahumma inni a'udhu bika min munkaratil-akhlaq': he ﷺ sought refuge from bad character, deeds and desires.",
  "When did he ﷺ seek refuge from sins and debt?": ["Bukhari 2397, from Aishah: 'kana yad'u fis-salah: Allahumma inni a'udhu bika minal-ma'thami wal-maghram.' When?", "On a journey", "At a feast", "At the market"],
  "What can debt lead a person to do, he ﷺ said?": ["Bukhari 2397: 'haddatha fa-kadhaba, wa wa'ada fa-akhlaf.' What does debt lead to?", "Sleep and rest more", "Eat and drink more", "Walk and travel more"],
  "He ﷺ often sought refuge with Allah from debt.": "In Bukhari 2397 someone asked why he ﷺ so often sought refuge from debt, and he said the debtor lies when he speaks and breaks his promises.",
  "What did Shakl ask him ﷺ to teach him?": ["Abu Dawud 1551: 'ya Rasulallah, 'allimni ta'awwudhan ata'awwadhu bih.' What did Shakl ask for?", "A poem", "A trade", "A letter"],
  "Which two come first in the du'a he ﷺ taught Shakl?": ["Abu Dawud 1551: 'min sharri sam'i wa min sharri basari.' Which two first?", "What I eat and what I drink", "What I buy and what I sell", "What I build and what I plant"],
  "The du'a he ﷺ taught also asks refuge from the evil of what we say.": "Abu Dawud 1551 seeks refuge from the evil of hearing, seeing, the tongue, the heart, and one more, five in one short dua.",
  "How many times could they count it in one sitting?": ["Tirmidhi 3434, from Ibn Umar: 'in kunna la-na'uddu li-Rasulillahi ﷺ fil-majlisil-wahid...' How many?", "Only once", "Three times", "Seven times"],
  "Besides forgiveness, what did he ﷺ ask Allah to accept?": ["Tirmidhi 3434: 'Rabbighfir li wa tub 'alayya.' What else was asked?", "His fasting", "His sadaqah", "His hajj"],
  "He ﷺ called Allah the Oft-Returning, the Most Forgiving.": "Tirmidhi 3434 ends 'innaka antat-Tawwabul-Ghafur': You are the Oft-Returning, the Most Forgiving.",
  "When did he ﷺ say Rabbighfir li, Rabbighfir li?": ["Ibn Majah 897, from Hudhayfah: 'kana yaqulu baynas-sajdatayn: Rabbighfir li.' When?", "After eating", "On waking up", "Before the adhan"],
  "What do you ask Allah for with Rabbighfir li?": ["Ibn Majah 897: 'Rabbighfir li, Rabbighfir li.' What is asked?", "Rain", "Food", "Wealth"],
  "He ﷺ asked Allah for forgiveness inside his prayer.": "Ibn Majah 897 says that between the two prostrations he ﷺ said 'Rabbighfir li, Rabbighfir li', asking forgiveness inside the prayer.",
  "What did he ﷺ say Allah will do for whoever says it?": ["Tirmidhi 3577: 'ghufira lahu wa in kana farra minaz-zahf.' What will Allah do?", "Give him a palace", "Give him much gold", "Give him a crown"],
  "Which two names follow la ilaha illa huwa in it?": ["Tirmidhi 3577: 'alladhi la ilaha illa huwal-____ wa atubu ilayh.' Which two names?", "Al-Khaliq, Al-Bari", "Al-Awwal, Al-Akhir", "Al-Malik, Al-Quddus"],
  "These words end with: wa atubu ilayh, and I repent to Him.": "Tirmidhi 3577: 'astaghfirullahal-'azimal-ladhi la ilaha illa huwal-Hayyul-Qayyumu wa atubu ilayh', forgiven even if he fled a battle.",
  "Who did he ﷺ give glad tidings to?": ["Ibn Majah 3818, from Abdullah ibn Busr: 'tuba li-man wajada fi sahifatihi istighfaran kathira.' To whom?", "Those with the most friends", "Those with the most gold", "Those with the biggest houses"],
  "Where will a person find their istighfar?": ["Ibn Majah 3818: 'wajada fi sahifatih.' Where does he find his istighfar?", "Under their pillow", "In a box of gold", "On a mountain top"],
  "Asking Allah for forgiveness a lot brings glad tidings.": "Ibn Majah 3818: 'tuba li-man wajada fi sahifatihi istighfaran kathira': glad tidings to one who finds much istighfar in his record.",
  "What did he ﷺ strike the dry tree with?": ["Tirmidhi 3533: 'marra bi-shajaratin yabisatil-waraq fa-darabaha bi-'asahu.' With what?", "A stone", "His hand", "His sandal"],
  "What do the four words make fall from a servant?": ["Tirmidhi 3533: the four words 'la-tusaqitu min dhunubil-'abd'. What falls?", "His happiness", "His good deeds", "His riches"],
  "Alhamdulillah and Subhanallah are among the four words.": "Tirmidhi 3533: al-hamdu lillah, subhanallah, la ilaha illallah and Allahu akbar make sins fall from the servant like the leaves of that tree.",
  "What did he ﷺ tell people to ask for their buried brother?": ["Abu Dawud 3221: 'istaghfiru li-akhikum wa salu lahut-tathbit.' What should they ask for him?", "A big house", "Gold and silver", "A long journey"],
  "Why did he ﷺ say to pray for him right then?": ["Abu Dawud 3221: 'fa-innahul-ana yus'al.' Why right then?", "He is hungry now", "He is asleep now", "He is far away"],
  "He ﷺ stood by the grave after a burial to make du'a.": "Abu Dawud 3221 tells that after a burial he ﷺ stood at the grave and said: ask forgiveness for your brother and firmness, for he is being questioned now.",
  "What did he ﷺ say the man had asked Allah by?": ["Tirmidhi 3475: 'laqad sa'alallaha bi-ismihil-a'zam.' What had the man asked Allah by?", "The name of a king", "The name of his father", "The name of an angel"],
  "Which two names of Allah were in the man's du'a?": ["Tirmidhi 3475: 'al-Ahadus-Samad, alladhi lam yalid wa lam yulad.' Which two names?", "Al-Khaliq, Al-Bari", "Al-Malik, Al-Quddus", "Ar-Rahman, Ar-Rahim"],
  "The man's du'a used words of Surah al-Ikhlas.": "Tirmidhi 3475: the man said 'al-Ahad, as-Samad, who does not beget, nor was begotten, and none is equal to Him', the words of Surah al-Ikhlas.",
  "Where was the man making his du'a?": ["Tirmidhi 3544, from Anas: a man prayed, then called on Allah as al-Mannan. Where was he?", "On a journey", "At his home", "In the market"],
  "What does Badi'us-samawati wal-ard mean?": ["Tirmidhi 3544: 'Badi'us-samawati wal-ard, ya Dhal-Jalali wal-Ikram.' What does the first part mean?", "Lord of the Throne", "Lord of the daybreak", "King of mankind"],
  "He ﷺ said the man called on Allah by His Greatest Name.": "In Tirmidhi 3544 he ﷺ said the man in the masjid who called on Allah as al-Mannan, Originator of the heavens and earth, had called on Allah by His Greatest Name.",
  "Who affirms the words of one who says La ilaha illallah wallahu akbar?": ["Tirmidhi 3430: 'saddaqahu Rabbuh: la ilaha illa ana wa ana akbar.' Who affirms him?", "The people near him", "His teacher", "His neighbors"],
  "What happens to one who says these words in illness, then dies?": ["Tirmidhi 3430: 'man qalaha fi maradihi thumma mat, lam tat'amhun-nar.' What is promised?", "He will be cured at once", "His wealth will grow", "He will be given gold"],
  "Allah answers the one who says La ilaha illallah wallahu akbar.": "Tirmidhi 3430 says that when a servant says la ilaha illallah wallahu akbar, his Lord affirms: none is worthy of worship but Me, and I am the Greatest.",
  "What does Rabbi a'inni mean?": ["Tirmidhi 3551, from Ibn Abbas: 'Rabbi a'inni wa la tu'in 'alayya.' What does the first part mean?", "My Lord, feed me", "My Lord, clothe me", "My Lord, hide me"],
  "What does waghsil hawbati mean?": ["Tirmidhi 3551: 'taqabbal tawbati waghsil hawbati.' What does the last part mean?", "Wash my face", "Wash my clothes", "Wash my hands"],
  "He ﷺ asked Allah to make him ever grateful to Him.": "Tirmidhi 3551: 'Rabbij'alni laka shakkaran, laka dhakkaran, laka rahhaba': make me ever grateful, ever remembering, ever fearful of You.",
  "What did the tree do in the man's dream?": ["Tirmidhi 3424, from Ibn Abbas: a man dreamt he prayed behind a tree. What did it do?", "Fell to the ground", "Gave him shade", "Grew sweet fruit"],
  "The du'a asks Allah to accept it as He accepted it from whom?": ["Tirmidhi 3424: 'wa taqabbalha minni kama taqabbaltaha min 'abdika ____.' Whom?", "Yunus", "Adam", "Nuh"],
  "Ibn Abbas heard him ﷺ say the same words in his sajdah.": "In Tirmidhi 3424 Ibn Abbas said he later heard him ﷺ recite a sajdah ayah and say in his sajdah the same words the man told of the tree.",
  "Who did he ﷺ give the first fruit to?": ["Tirmidhi 3454: after the dua over the first fruit, 'yad'u asghara walidin yarah.' To whom did it go?", "The oldest man there", "The richest trader", "The first man he saw"],
  "Along with their fruits, what did he ﷺ ask Allah to bless?": ["Tirmidhi 3454: 'barik lana fi thimarina wa barik lana fi ____.' What else?", "Their markets", "Their ships", "Their clothes"],
  "He ﷺ asked for Madinah what Ibrahim had asked for Makkah.": "Tirmidhi 3454: he ﷺ asked for Madinah the like of what Ibrahim asked for Makkah, and as much again with it.",
  "What fear did he ﷺ ask Allah for, before standing up from a sitting?": ["Tirmidhi 3502: 'Allahumma-qsim lana min khashyatika ma yahulu baynana wa bayna ma'asik.' What fear?", "Fear of the sea", "Fear of the cold", "Fear of the dark"],
  "In his ﷺ du'a for fear of Allah, what should certainty make easy?": ["Tirmidhi 3502: 'wa minal-yaqini ma tuhawwinu bihi 'alayna musibatid-dunya.' What does certainty ease?", "The length of the road", "The heat of summer", "The cold of winter"],
  "He ﷺ asked Allah for obedience that brings us to Paradise.": "Tirmidhi 3502: 'wa min ta'atika ma tuballighuna bihi jannatak': obedience to You that brings us to Your Paradise.",
  "Which du'as did he ﷺ like best?": ["Abu Dawud 1482, from Aishah: 'kana yastahibbul-jawami'a minad-du'a.' Which duas did he ﷺ like?", "Ones nobody understands", "Ones in rhyming words", "Ones shouted out loud"],
  "What did he ﷺ do with other kinds of du'a?": ["Abu Dawud 1482: 'wa yada'u ma siwa dhalik.' What did he ﷺ do with other kinds?", "He wrote them on walls", "He made them longer", "He said them first"],
  "A short du'a can hold a great deal of good.": "Abu Dawud 1482 says he ﷺ liked jawami' ad-du'a, duas of few words that gather much good, and left other kinds.",
  "What does the du'a ask Allah for first?": ["Ibn Majah 3846: 'Allahumma inni as'aluka minal-khayri kullih.' What first?", "Gold and silver", "Fame among people", "A big house"],
  "Which good does the du'a ask for?": ["Ibn Majah 3846: ''ajilihi wa ajilih, ma 'alimtu minhu wa ma lam a'lam.' Which good?", "Only what others have", "Only what we can see", "Only what we have now"],
  "The du'a she was taught asks for Paradise too.": "In Ibn Majah 3846 he ﷺ taught Aishah to ask for all good, for Paradise and every word or deed that brings near to it.",
  "Which three du'as are answered, with no doubt?": ["Abu Dawud 1536: 'thalathu da'awatin mustajabat la shakka fihinn.' Which three?", "A king, a poet, a trader", "A guest, a tailor, a cook", "A rich man, a judge, a builder"],
  "How sure is it that these du'as are answered?": ["Abu Dawud 1536: 'mustajabatun la shakka fihinn.' How sure?", "Only now and then", "Hardly ever", "Only on Fridays"],
  "When someone is wronged, Allah answers his du'a.": "Abu Dawud 1536 counts the dua of the wronged among three answered with no doubt, with the father's and the traveller's.",
  "When is a du'a not turned back, he ﷺ said?": ["Abu Dawud 521, from Anas: 'la yuraddud-du'a'u baynal-adhani wal-____.' Fill it in.", "Only after Eid", "Only while eating", "Only at noon"],
  "What is a good way to spend the wait for the iqamah?": ["Abu Dawud 521: 'la yuraddud-du'a'.' You sit waiting for the iqamah. What fits best?", "Walking out of the masjid", "Playing with a phone", "Chatting about the market"],
  "The wait before the prayer starts is a good time for du'a.": "Abu Dawud 521 says a dua made between the adhan and the iqamah is not turned back.",
  "Where did Abu Bakr stand and weep?": ["Tirmidhi 3558, from Rifa'ah: 'qama Abu Bakr 'alal-minbar thumma baka.' Where did he weep?", "At the city gate", "In the market", "On a hilltop"],
  "What two things did he ﷺ tell us to ask Allah for?": ["Tirmidhi 3558: 'salullahal-'afwa wal-'afiyah.' Which two?", "Riches and fame", "Power over people", "Gold and silver"],
  "No one is given anything better than well-being.": "In Tirmidhi 3558 Abu Bakr wept on the minbar and said: ask Allah for pardon and well-being, for none is given better than well-being after certainty.",
  "What had the sick man been asking Allah for?": ["Muslim 2688a: 'ma kunta mu'aqibi bihi fil-akhirah fa-'ajjilhu li fid-dunya.' What had he asked for?", "To be made a king in this world", "To be made rich in this world", "To be made famous in this world"],
  "What had the sick man become like?": ["Muslim 2688a: 'qad khafata fa-sara mithlal-farkh.' He had become like what?", "A strong young lion", "A tall old tree", "A fast wild horse"],
  "We should not ask Allah to rush His punishment onto us.": "In Muslim 2688a he ﷺ told the sick man not to ask for punishment now, but to say 'Rabbana atina fid-dunya hasanah...' instead.",
  "What kind of knowledge should we ask Allah for?": ["Ibn Majah 3843, from Jabir: 'salullaha 'ilman nafi'a.' What knowledge?", "Knowledge to show off", "Knowledge of magic", "Knowledge to win arguments"],
  "What should we seek refuge with Allah from?": ["Ibn Majah 3843: 'wa ta'awwadhu billahi min 'ilmin la yanfa'.' Refuge from what?", "Reading good books", "Teaching others", "Learning the Quran"],
  "We can ask Allah to make our learning useful.": "Ibn Majah 3843 says to ask Allah for knowledge that benefits and to seek refuge in Him from knowledge that does not.",
  "Which part of the hands did he ﷺ say to ask Allah with?": ["Abu Dawud 1486: 'fas'aluhu bi-butuni akuffikum wa la tas'aluhu bi-zuhuriha.' Which part?", "The knuckles", "The thumbs", "The fingernails"],
  "When did he ﷺ say to hold up the palms of your hands?": ["Abu Dawud 1486: 'idha sa'altumullaha fas'aluhu bi-butuni akuffikum.' When?", "When walking in the market", "When sitting down to eat", "When going out of the house"],
  "He ﷺ taught us to ask Allah with the palms of our hands.": "Abu Dawud 1486 says that when you ask Allah, ask Him with the palms of your hands, not with their backs.",
  "How many times does the visitor say the du'a?": ["Tirmidhi 2083: 'as'alullahal-'Azim, Rabbal-'arshil-'azim, an yashfiyak', how many times?", "Forty", "Once", "Twice"],
  "Whom do we ask to cure the sick person?": ["Tirmidhi 2083: 'Rabbal-'arshil-'azim an yashfiyak.' Whom do we ask?", "The stars", "A lucky charm", "The wind"],
  "We can make du'a for a sick friend when we visit.": "Tirmidhi 2083 says that whoever visits a sick man whose time has not come and says it seven times, Allah will cure him.",
  "What did the host ask for as he ﷺ was leaving?": ["Abu Dawud 3729: 'fa-akhadha abi bi-lijami dabbatih: ud'ullaha lana.' What did the host ask?", "A new camel", "A book of poems", "A gift of gold"],
  "What did he ﷺ ask Allah to bless them in?": ["Abu Dawud 3729: 'Allahumma barik lahum fima razaqtahum.' Bless them in what?", "Their fame", "Their big houses", "Their fine clothes"],
  "A guest can make du'a for the people who fed him.": "Abu Dawud 3729 says that leaving Abdullah ibn Busr's father he ﷺ prayed: bless them in what You provided, forgive them, have mercy on them.",
  "What did Sa'd bring him ﷺ to eat?": ["Abu Dawud 3854, from Anas: he ﷺ came to Sa'd ibn Ubadah, who brought 'khubzin wa zayt'. What?", "Honey cakes", "Roast meat", "Dates and milk"],
  "In his du'a, who would pray for blessing on Sa'd's family?": ["Abu Dawud 3854: 'aftara 'indakumus-sa'imun... wa sallat 'alaykumul-____.' Who prays for blessing?", "The traders", "The poets", "The guards"],
  "He ﷺ prayed that the pious would eat Sa'd's food.": "In Abu Dawud 3854 he ﷺ prayed: may the fasting break their fast with you, the pious eat your food, and the angels pray for you.",
  "When did he ﷺ say the du'a for our living and our dead?": ["Abu Dawud 3201: 'Allahummaghfir li-hayyina wa mayyitina.' When did he ﷺ say it?", "At a wedding feast", "On the way to market", "At the Eid meal"],
  "Whom did he ﷺ ask Allah to forgive?": ["Abu Dawud 3201: 'li-hayyina wa mayyitina, wa saghirina wa kabirina.' Whom first?", "Only our men", "Only our old", "Only those present"],
  "Our young and our old are named in the du'a.": "Abu Dawud 3201: 'wa saghirina wa kabirina, wa dhakarina wa unthana': our young and old, our men and women.",
  "Why did at-Tufail ask him ﷺ to pray against Daws?": ["Bukhari 6397: 'inna Dawsan qad 'asat wa abat.' Why did at-Tufail ask him ﷺ to pray against them?", "They were too few", "They had no water", "They lived far away"],
  "What did he ﷺ ask Allah for, for Daws?": ["Bukhari 6397: 'Allahummahdi Dawsan wa'ti bihim.' What did he ﷺ ask for?", "Wealth for them", "Rain for them", "Fame for them"],
  "People thought he ﷺ would pray against Daws.": "In Bukhari 6397, when at-Tufail asked him ﷺ to pray against Daws, it was said 'Daws is ruined', but he prayed for their guidance.",
  "For which people did he ﷺ make du'a?": ["Bukhari 2130: 'Allahumma barik lahum fi mikyalihim, wa barik lahum fi sa'ihim wa muddihim.' For whom?", "The people of Persia", "The traders of Egypt", "The people of Rome"],
  "What did he ﷺ ask Allah to bless?": ["Bukhari 2130: 'barik lahum fi mikyalihim.' Bless what?", "Their horses", "Their palaces", "Their city walls"],
  "The mudd and the sa' were used to measure food.": "In Bukhari 2130, the mudd and the sa' he ﷺ asked Allah to bless for the people of Madinah were measures for food.",
  "When did he ﷺ remember Allah, Aishah said?": ["Muslim 373, from Aishah: 'kana yadhkurullaha 'ala kulli ahyanih.' When?", "Only on Fridays", "Only in Ramadan", "Only when traveling"],
  "What is dhikr?": ["Muslim 373: 'yadhkurullaha 'ala kulli ahyanih.' What is dhikr, as he ﷺ did it?", "Counting your money", "Reading poems aloud", "Telling old stories"],
  "Dhikr is only for after the five prayers.": "By Muslim 373, he ﷺ kept dhikr only for the times after the obligatory prayers.",
  "When is Allah with His servant, Allah says?": ["Ibn Majah 3792, a hadith qudsi: 'ana ma'a 'abdi idha huwa dhakarani.' When?", "When people praise him", "When he is the richest", "When he wins a fight"],
  "What moves when the servant remembers Allah?": ["Ibn Majah 3792: 'wa taharrakat bi shafatah.' What moves with His name?", "His toes", "His ears", "His shoulders"],
  "Quiet dhikr with moving lips is remembering Allah.": "Ibn Majah 3792: Allah says He is with His servant when he remembers Him and his lips move with His name.",
  "Who are the mufarridun, he ﷺ said?": ["Muslim 2676: 'sabaqal-mufarridun.' They asked who they are. He ﷺ said?", "Those who travel far", "Those who own mountains", "Those who sleep early"],
  "Where was he ﷺ when he spoke of the mufarridun?": ["Muslim 2676: 'kana yasiru fi tariqi Makkah fa-marra 'ala jabalin yuqalu lahu Jumdan.' Where was he?", "In a garden in Ta'if", "In a market in Syria", "On a ship at sea"],
  "Women who remember Allah much are among the mufarridun too.": "Muslim 2676: 'adh-dhakirunallaha kathiran wadh-dhakirat': men and women who remember Allah much have gone ahead.",
  "Leaving a gathering with no dhikr is like leaving what?": ["Abu Dawud 4855: 'illa qamu 'an mithli jifati himar.' Like leaving what?", "A fresh garden", "A full well", "A happy feast"],
  "What will a gathering with no dhikr bring them?": ["Abu Dawud 4855: 'wa kana lahum hasrah.' What will it bring them?", "New wealth", "Great reward", "More friends"],
  "Friends sitting together should remember Allah in their talk.": "Abu Dawud 4855 says people who rise from a gathering where they did not remember Allah rise as if from a dead donkey, and it brings them regret.",
  "What did he ﷺ ask Allah for before sleeping?": ["Tirmidhi 3399: 'Rabbi qini 'adhabaka yawma tab'athu 'ibadak.' What did he ﷺ ask?", "A big dinner", "A soft bed", "A long sleep"],
  "Where did he ﷺ rest his head when going to sleep?": ["Tirmidhi 3399: 'tawassada yaminah.' Where did he ﷺ rest his head?", "On a pile of books", "On a tree trunk", "On his left hand"],
  "He ﷺ remembered Allah even as he lay down to sleep.": "Tirmidhi 3399, from Al-Bara: resting his head on his right hand, he ﷺ said: my Lord, guard me from Your punishment the Day You resurrect Your servants.",
  "What opens for la ilaha illallah said sincerely?": ["Tirmidhi 3590: 'ma qala 'abdun la ilaha illallahu mukhlisan qattu illa futihat lahu ____.' What opens?", "The windows of the house", "The doors of the market", "The gates of the city"],
  "How far does sincere la ilaha illallah rise?": ["Tirmidhi 3590: 'hatta tufdiya ilal-'arsh.' How far?", "To the mountain tops", "To the roof of the masjid", "To the clouds only"],
  "Keeping away from major sins matters for la ilaha illallah to rise.": "Tirmidhi 3590 says the gates of heaven open for la ilaha illallah said sincerely until it reaches the Throne, 'majtanaba al-kaba'ir', so long as major sins are avoided.",
  "Which two evils did he ﷺ seek refuge from, Aishah said?": ["Abu Dawud 1550: 'min sharri ma 'amiltu wa min sharri ma lam a'mal.' Which two evils?", "What he had bought and sold", "What he had built and planted", "What he had eaten and drunk"],
  "Whom did Farwah ibn Nawfal ask about his ﷺ du'a?": ["Abu Dawud 1550: Farwah ibn Nawfal asked her about his ﷺ dua. Whom did he ask?", "Umm Salamah", "Maymunah", "Hafsah"],
  "He ﷺ sought refuge even from the evil of what he had not done.": "Abu Dawud 1550 says he ﷺ sought refuge from the evil of what he had done and the evil of what he had not done.",
  "When did he ﷺ teach Asma to say these words?": ["Ibn Majah 3882: 'Allahu Allahu Rabbi la ushriku bihi shay'a', taught to Asma bint Umays for when?", "At the start of a meal", "On the night of Eid", "When buying new clothes"],
  "What does la ushriku bihi shay'a mean?": ["Ibn Majah 3882: 'la ushriku bihi shay'a.' What does it mean?", "I forget nothing about Him", "I hide nothing from Him", "I ask Him for nothing"],
  "He ﷺ taught Asma bint Umays words for hard times.": "Ibn Majah 3882 says he ﷺ taught Asma bint Umays to say at times of distress: Allah, Allah is my Lord, I associate nothing with Him.",
  "Who are Jibril, Mikail and Israfil?": ["Nasa'i 5519: 'Allahumma Rabba Jibra'ila wa Mika'ila wa Israfil.' Who are they?", "Prophets", "Companions", "Jinn"],
  "From the heat of what did he ﷺ seek refuge?": ["Nasa'i 5519: 'a'udhu bika min harrin-nar.' The heat of what?", "The summer sun", "The desert sand", "The cooking pot"],
  "He ﷺ sought refuge from the torment of the grave.": "Nasa'i 5519: 'Lord of Jibra'il, Mika'il and Israfil, I seek refuge in You from the heat of the Fire and the torment of the grave.'",
  "Which three things did he ﷺ ask Allah to set right?": ["Muslim 2720: 'aslih li dini... wa aslih li dunyaya... wa aslih li akhirati.' Which three?", "House, horse and garden", "Friends, food and sleep", "Clothes, shoes and tent"],
  "In his ﷺ du'a, what is in this world for us?": ["Muslim 2720: 'dunyayal-lati fiha ____.' What is in this world for us?", "Our final home", "Our only goal", "Our full reward"],
  "He ﷺ asked Allah to make death a rest from every evil.": "Muslim 2720: 'waj'alil-mawta rahatan li min kulli sharr': make death a rest for me from every evil.",
  "From which neighbor did he ﷺ tell us to seek refuge?": ["Nasa'i 5502: 'ta'awwadhu billahi min jaris-su'i fi dari muqam.' Which neighbor?", "A neighbor who visits", "A neighbor far away", "A neighbor on a journey"],
  "Why is a bad neighbor on a journey less of a worry?": ["Nasa'i 5502: 'fa-inna jaral-badiyati yatahawwalu 'ank.' Why is the desert neighbor less worry?", "He is always kind", "He never says a word", "He has no house"],
  "We should seek refuge with Allah from a bad neighbor.": "Nasa'i 5502 says to seek refuge from a bad neighbor where you live for good, for a neighbor in the desert soon moves on.",
  "What did Abdullah ibn Amr see him ﷺ count on his hand?": ["Tirmidhi 3486: 'ra'aytun-nabiyya ﷺ ya'qidut-tasbih biyadih.' What did he count?", "The leaves of a tree", "The stars in the sky", "The grains of sand"],
  "What is tasbih?": ["Tirmidhi 3486: 'ya'qidut-tasbih.' What is tasbih?", "Saying Amin", "Saying Insha Allah", "Saying Bismillah"],
  "Abdullah ibn Amr saw him ﷺ counting the tasbih on his hand.": "Tirmidhi 3486: Abdullah ibn Amr said 'I saw the Prophet ﷺ counting the tasbih on his hand'.",
  "Who came to Ali asking for help?": ["Tirmidhi 3563: 'inni 'ajaztu 'an kitabati fa-a'inni.' Who came to Ali?", "A trader who lost his goods", "A farmer whose crops failed", "A traveler who lost his camel"],
  "What does the du'a ask Allah to make enough for us?": ["Tirmidhi 3563: 'Allahummakfini bi-halalika 'an haramik.' Make what enough?", "What we take by force", "What belongs to others", "What we find by chance"],
  "In this du'a, we ask Allah to make us need no one but Him.": "Tirmidhi 3563: 'wa aghnini bi-fadlika 'amman siwak': make me free of need of all besides You by Your bounty.",
  "How many good deeds are written for a hundred tasbih?": ["Tirmidhi 3463, from Sa'd: 'yusabbihu mi'ata tasbihah, fa-yuktabu lahu ____.' How many good deeds?", "Ten good deeds", "Seventy good deeds", "Forty good deeds"],
  "Who asked how one could earn them?": ["Tirmidhi 3463: 'a-ya'jizu ahadukum an yaksiba kulla yawmin alfa hasanah?' Who asked how?", "A trader in the market", "A shepherd on a hill", "A king from far away"],
  "He ﷺ asked if anyone was unable to earn a thousand good deeds.": "In Tirmidhi 3463 he ﷺ asked 'is any of you unable to earn a thousand good deeds each day?', then said: a hundred tasbih.",
  "When did he ﷺ say to praise Allah with these words?": ["Tirmidhi 3458, from Mu'adh ibn Anas: 'man akala ta'aman thumma qal: al-hamdu lillahil-ladhi at'amani hadha.' When?", "On leaving home", "Before going to sleep", "On waking up"],
  "How did we get our food, the du'a says?": ["Tirmidhi 3458: 'min ghayri hawlin minni wa la quwwah.' How did we get it?", "A king gave it to us", "We found it by chance", "We earned it by our strength"],
  "His past sins are forgiven for saying it after food.": "Tirmidhi 3458 says whoever eats and then says 'praise be to Allah who fed me this... without effort or power from me' has his past sins forgiven.",
  "Who can have sins pardoned by saying these words?": ["Tirmidhi 3460: 'ma 'alal-ardi ahadun yaqul... illa kuffirat 'anhu khatayahu wa law kanat mithla zabadil-bahr.' Who?", "Only the elderly", "Only those in Makkah", "Only the scholars"],
  "Which words begin this dhikr?": ["Tirmidhi 3460: '____, wallahu akbar, wa la hawla wa la quwwata illa billah.' What begins it?", "Astaghfirullah", "Subhan Allah", "Alhamdulillah"],
  "These words include Allahu akbar, Allah is the Greatest.": "Tirmidhi 3460: 'la ilaha illallah, wallahu akbar, wa la hawla wa la quwwata illa billah' pardons sins even like the foam of the sea.",
  "What did the man ask Allah for after the tashahhud?": ["Ibn Majah 3847: 'atashahhadu thumma aqul: Allahumma inni as'alukal-jannah.' What did the man ask?", "Many children", "Gold", "A long life"],
  "What did he ﷺ say his quiet du'as were about?": ["Ibn Majah 3847: 'la uhsinu dandanataka wa la dandanata Mu'adh.' He ﷺ said 'hawlaha nudandin'. Around what?", "Wealth and trade", "Homes and land", "Fame and power"],
  "Asking for Paradise and refuge from the Fire is a fine du'a.": "In Ibn Majah 3847 the man asked only for Paradise and refuge from the Fire, and he ﷺ said: it is around these that we whisper.",
  "What did the son ask for in his du'a?": ["Ibn Majah 3864: 'Allahumma inni as'alukal-qasral-abyad 'an yaminil-jannah.' What did the son ask?", "A grand house in town", "A fast horse", "A tall palm tree"],
  "What did his father tell him to ask for instead?": ["Ibn Majah 3864: 'ya bunayya, salillahal-jannah wa 'udh bihi minan-nar.' What instead?", "Fame, and many friends", "Power, and a big house", "Wealth, and a long life"],
  "He ﷺ said some people will go too far in du'a.": "Ibn Majah 3864: Abdullah ibn Mughaffal heard him ﷺ say 'sayakunu qawmun ya'taduna fid-du'a': people will go too far in dua.",
  "When are these words said, he ﷺ taught?": ["Tirmidhi 210: 'man qala hina yasma'ul-mu'adhdhin: wa ana ashhadu an la ilaha illallah.' When?", "On entering the market", "On putting on new clothes", "On seeing the rain"],
  "Which of these is in the words he ﷺ taught?": ["Tirmidhi 210: 'raditu billahi Rabban, wa bi-Muhammadin rasulan, wa bil-islami dina.' Which is in it?", "Pleased with my wealth", "Pleased with my tribe", "Pleased with my fame"],
  "Saying these words on hearing the mu'adhdhin brings pardon.": "Tirmidhi 210 says whoever, on hearing the mu'adhdhin, says he is pleased with Allah as Lord, Muhammad ﷺ as Messenger and Islam as religion, is forgiven.",
  "What did he ﷺ ask Allah for the imams?": ["Abu Dawud 517: 'al-imamu damin... Allahumma arshidil-a'immah.' What for the imams?", "Fame", "Long life", "Wealth"],
  "What did he ﷺ ask Allah for the mu'adhdhins?": ["Abu Dawud 517: 'wal-mu'adhdhinu mu'taman... waghfir lil-mu'adhdhinin.' What for them?", "Many children", "Riches", "Strong voices"],
  "He ﷺ called the mu'adhdhin one who is trusted.": "Abu Dawud 517: 'the imam is responsible and the mu'adhdhin is trusted; O Allah, guide the imams and forgive the mu'adhdhins.'",
  "How many times is each one said, he ﷺ taught?": ["Nasa'i 1299: 'kabbirillaha 'ashran, wa sabbihillaha 'ashran, wahmadihi 'ashran.' How many times?", "Once each", "Three times each", "A hundred times each"],
  "Who asked him ﷺ for words to say in her prayer?": ["Nasa'i 1299: ''allimni kalimatin ad'u bihinna fi salati.' Who asked?", "Asma bint Abi Bakr", "Umm Ayman", "Umm Haram"],
  "After the ten of each, she was told to ask for her needs.": "Nasa'i 1299: after ten takbir, ten tasbih and ten tahmid, she asks for what she needs and Allah says: yes, yes.",
  "What did he ﷺ ask Allah to place in his heart?": ["Abu Dawud 1353, from Ibn Abbas: 'Allahummaj'al fi qalbi ____.' What?", "Sleep", "Gold", "Fame"],
  "Which of these is in his ﷺ du'a for light?": ["Abu Dawud 1353: 'wa fi sam'i nuran, wa fi basari nura.' Which is named?", "Light in my pocket", "Light on my sword", "Light in my bag"],
  "He ﷺ asked Allah to give him abundant light.": "In Abu Dawud 1353 Ibn Abbas, staying the night at his ﷺ house, heard him ask for light in the heart, the hearing, all around, and 'a'zim li nura'.",
  "How many rak'ahs are prayed for the istikharah?": ["Bukhari 1166: 'fal-yarka' rak'atayni min ghayril-faridah.' How many rak'ahs?", "One rak'ah only", "Six in a row", "Four, with the obligatory"],
  "In what matters did he ﷺ teach the istikharah?": ["Bukhari 1166: 'yu'allimunal-istikharata fil-umuri kulliha kama yu'allimunas-surah.' In which matters?", "Only in trade", "Only in travel", "Only in marriage"],
  "In the istikharah we say: You know and I do not.": "In Bukhari 1166 the istikharah says 'fa-innaka taqdiru wa la aqdir, wa ta'lamu wa la a'lam, wa anta 'allamul-ghuyub'.",
  "Before which prayer are these four rak'ahs?": ["Abu Dawud 1271: 'rahimallahumra'an salla qablal-'asri arba'a.' Before which prayer?", "Isha, the night prayer", "Fajr, the dawn prayer", "Maghrib, the sunset prayer"],
  "What did he ﷺ ask Allah for, for that man?": ["Abu Dawud 1271: 'rahimallahumra'an...' What did he ﷺ ask for him?", "Riches", "A long life", "A big house"],
  "Four rak'ahs before Asr bring his ﷺ du'a for mercy.": "Abu Dawud 1271: 'rahimallahumra'an salla qablal-'asri arba'a': he ﷺ prayed for mercy on one who prays four rak'ahs before Asr.",
  "When was Uqbah told to recite the Mu'awwidhat?": ["Abu Dawud 1523, from Uqbah: 'amarani an aqra'a bil-mu'awwidhati fi duburi kulli salah.' When?", "Only in Ramadan", "Only on Eid", "Only on Friday"],
  "Who said he was told to recite them after every prayer?": ["Abu Dawud 1523: 'amarani Rasulullahi ﷺ an aqra'a bil-mu'awwidhat.' Who was told?", "Zayd ibn Thabit", "Salman al-Farisi", "Bilal ibn Rabah"],
  "The Mu'awwidhat are recited after every prayer.": "Abu Dawud 1523: Uqbah ibn Amir said he ﷺ commanded him to recite the Mu'awwidhat after every prayer.",
  "In the witr du'a, we ask to be guided among whom?": ["Abu Dawud 1425, from al-Hasan ibn Ali: 'Allahummahdini fiman hadayt.' Among whom?", "Those who are famous", "Those who are strong", "Those who are rich"],
  "From what do we ask Allah to guard us, in the witr du'a?": ["Abu Dawud 1425: 'wa qini sharra ma qadayt.' Guard from what?", "The heat of the summer", "The noise of the market", "The cold of the night"],
  "The one whom Allah befriends is never humbled, the du'a says.": "Abu Dawud 1425: 'innahu la yadhillu man walayt': the one You befriend is never humbled; blessed are You, our Lord, and exalted.",
};
